	@Override
	protected void startUp()
	{
		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/icon.png");

		navButton = NavigationButton.builder()
			.tooltip("TRIGLAV")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		panel.showLinked(keyStore.isLinked(), null);
		panel.setOnLink(this::linkCode);
		panel.setOnSendGear(title -> gearClient.sendCurrentSetup(title, result -> chat("TRIGLAV: " + result)));
		feedClient.setSink(this::showFeedMessage);
		panel.setOnShare(this::shareWithClan);
		panel.setOnCreateLfg(this::createLfg);
		panel.setOnCheckGear(this::checkLfgGear);
		panel.setOnJoinLfg((postId, leave) -> overviewClient.joinLfg(postId, leave, result -> chat("TRIGLAV: " + result)));
		overviewClient.setListener(overview -> panel.showOverview(overview, keyStore.isLinked()));
		bingoClient.setAnnouncer(message ->
		{
			if (config.inGameMessages())
			{
				chat(message);
			}
		});
		overlayManager.add(bingoOverlay);
		overlayManager.add(locationOverlay);
		// Enabled while already in game: send the login snapshot on the next tick.
		lastGameState = client.getGameState();
		loginPending = lastGameState == GameState.LOGGED_IN;

		// Re-check the stored code on every start: picks up a code changed on the site ("zamenjaj kodo").
		keyStore.refresh(result -> onLinkResult(result, false));
	}

	@Override
	protected void shutDown()
	{
		lfgReminder.shutDown();
		locationSharer.clear();
		if (autoGearTask != null)
		{
			autoGearTask.cancel(false);
		}
		overlayManager.remove(bingoOverlay);
		overlayManager.remove(locationOverlay);
		clientToolbar.removeNavigation(navButton);
	}

	@Provides
	TriglavConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(TriglavConfig.class);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		final GameState state = event.getGameState();

		if (state == GameState.LOGGED_IN && lastGameState != GameState.LOGGED_IN)
		{
			// The local player (and its name) isn't loaded yet on this event; onGameTick sends it.
			loginPending = true;
		}
		else if (lastGameState == GameState.LOGGED_IN
			&& (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.CONNECTION_LOST))
		{
			sendLogout();
		}

		lastGameState = state;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		// Only the game's own messages: a player could otherwise type "Your Zulrah kill count is:
		// 1000" in public chat and have it reported as theirs.
		final ChatMessageType type = event.getType();
		if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM
			&& type != ChatMessageType.FRIENDSCHATNOTIFICATION)
		{
			return;
		}

		killCountTracker.onChatMessage(event);
		petDetector.onChatMessage(event);

		final String clogItem = CollectionLogChat.newItemName(event);
		if (clogItem != null)
		{
			// The log counters update a tick after the message; the site draws its progress bar from them.
			clientThread.invokeLater(() ->
			{
				final JsonObject extra = new JsonObject();
				extra.addProperty("itemName", clogItem);
				final JsonObject progress = CollectionLogTotals.snapshot(client);
				if (progress != null)
				{
					extra.addProperty("completedEntries", progress.get("completed").getAsInt());
					extra.addProperty("totalEntries", progress.get("total").getAsInt());
				}
				apiClient.send(Envelope.create(client, "COLLECTION", extra), null);
			});
		}

		final JsonObject clue = ClueChat.parse(event);
		if (clue != null)
		{
			apiClient.send(Envelope.create(client, "CLUE", clue), null);
		}

		final JsonObject slayer = slayerChat.parse(event);
		if (slayer != null)
		{
			apiClient.send(Envelope.create(client, "SLAYER", slayer), null);
		}

		// The combat achievement point varbits are only updated a tick after the message.
		final String message = Text.removeTags(event.getMessage());
		if (message.startsWith("Congratulations, you've completed a"))
		{
			clientThread.invokeLater(() ->
			{
				final JsonObject task = combatTaskTracker.parse(client, message);
				if (task != null)
				{
					apiClient.send(Envelope.create(client, "COMBAT_ACHIEVEMENT", task), null);
				}
			});
		}
	}

	/** One upload half a minute after the last equipment change, so swapping gear in a bank does not spam. */
	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.EQUIPMENT.getId() || !config.autoSendGear()
			|| client.getGameState() != GameState.LOGGED_IN || !keyStore.isLinked())
		{
			return;
		}

		if (autoGearTask != null)
		{
			autoGearTask.cancel(false);
		}
		autoGearTask = executor.schedule(() -> gearClient.sendCurrentSetup("", true, result ->
		{
		}), AUTO_GEAR_DELAY_SECONDS, TimeUnit.SECONDS);
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		levelTracker.onStatChanged(event);
		xpMilestoneTracker.onStatChanged(event);
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		playerKillTracker.onHitsplat(client, event);
	}

	/** The quest completion scroll; its counts land one tick later, hence the invokeLater. */
	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() != QuestTracker.WIDGET_GROUP)
		{
			return;
		}

		final String title = questTracker.title(client);
		if (questTracker.isPartial(title))
		{
			return;
		}
		clientThread.invokeLater(() ->
			apiClient.send(Envelope.create(client, "QUEST", questTracker.build(client, title)), null));
	}

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		sendLoot(lootCollector.build(event));
	}

	/**
	 * Loot that is not an NPC drop: raid chests, clue caskets, implings, pickpocketing. NPC loot
	 * also fires this event, but it is already handled above (with the kill count attached), and a
	 * killed player is reported as a PK rather than as loot.
	 */
	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		if (event.getType() == LootRecordType.NPC || event.getType() == LootRecordType.PLAYER)
		{
			return;
		}

		sendLoot(lootCollector.build(event.getName(), event.getType().name(), event.getItems()));
	}

	private void sendLoot(JsonObject extra)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		final JsonObject envelope = Envelope.create(client, "LOOT", extra);

		final BingoBoard board = bingoClient.board();
		if (board != null)
		{
			for (JsonElement item : extra.getAsJsonArray("items"))
			{
				if (board.hasOpenTileFor(item.getAsJsonObject().get("id").getAsInt()))
				{
					bingoClient.refreshSoon();
					break;
				}
			}
		}

		if (!config.sendScreenshots() || LootValue.total(extra.getAsJsonArray("items")) < configClient.current().screenshotMinValue)
		{
			apiClient.send(envelope, null);
			return;
		}

		captureScreenshot(png -> apiClient.send(envelope, png));
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		final String petName = petDetector.onNpcSpawned(client, event);
		if (petName != null)
		{
			final JsonObject extra = new JsonObject();
			extra.addProperty("petName", petName);
			apiClient.send(Envelope.create(client, "PET", extra), null);
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (event.getActor() == client.getLocalPlayer())
		{
			deathTracker.onLocalPlayerDied(client);
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		final String name = Envelope.playerName(client);
		if (name != null)
		{
			if (!name.equals(lastPlayerName))
			{
				// LFG is per RSN: tell the clients which character plays (also after switching accounts)
				overviewClient.setRsn(name);
				lfgClient.setRsn(name);
				overviewClient.refreshNow();
			}
			lastPlayerName = name;
			if (loginPending)
			{
				loginPending = false;
				sendLogin();
				clanRankReporter.reportNow();
			}
		}

		petDetector.onGameTick();
		lfgReminder.onGameTick(this, message -> chat("TRIGLAV: " + message));
		locationSharer.onGameTick();

		final JsonObject deathExtra = deathTracker.onGameTick(client);
		if (deathExtra != null && config.sendDeaths())
		{
			apiClient.send(Envelope.create(client, "DEATH", deathExtra), null);
		}

		final JsonObject levelExtra = levelTracker.onGameTick(client);
		if (levelExtra != null)
		{
			apiClient.send(Envelope.create(client, "LEVEL", levelExtra), null);
		}

		final JsonObject xpExtra = xpMilestoneTracker.onGameTick();
		if (xpExtra != null)
		{
			apiClient.send(Envelope.create(client, "XP_MILESTONE", xpExtra), null);
		}

		final JsonObject killCountExtra = killCountTracker.onGameTick();
		if (killCountExtra != null)
		{
			apiClient.send(Envelope.create(client, "KILL_COUNT", killCountExtra), null);
		}

		final List<JsonObject> kills = playerKillTracker.onGameTick(client);
		if (kills != null)
		{
			for (JsonObject kill : kills)
			{
				apiClient.send(Envelope.create(client, "PLAYER_KILL", kill), null);
			}
		}
	}

	private void sendLogin()
	{
		// The level-up tracker needs a baseline: StatChanged fires for every skill right after login.
		levelTracker.prime(client);
		xpMilestoneTracker.prime(client);

		final JsonObject extra = new JsonObject();
		extra.add("skills", SkillSnapshot.build(client));
		extra.add("slayer", SlayerSnapshot.build(client));
		extra.add("achievementDiary", DiarySnapshot.build(client));
		final JsonObject collectionLog = CollectionLogTotals.snapshot(client);
		if (collectionLog != null)
		{
			extra.add("collectionLog", collectionLog);
		}
		apiClient.send(Envelope.create(client, "LOGIN", extra), null);
		log.debug("TRIGLAV: sent LOGIN snapshot");
	}

	private void sendLogout()
	{
		// The player is already gone at this point, so use the name seen while logged in.
		apiClient.send(Envelope.create(client, "LOGOUT", new JsonObject(), lastPlayerName), null);
		log.debug("TRIGLAV: sent LOGOUT");

		// Half-finished state must not carry over to the next character or world.
		levelTracker.reset();
		xpMilestoneTracker.reset();
		locationSharer.clear();
		killCountTracker.reset();
		slayerChat.reset();
		playerKillTracker.reset();
	}

	/** The clan channel loads a few seconds after login; report the ranks once it's actually there. */
	@Subscribe
	public void onClanChannelChanged(ClanChannelChanged event)
	{
		if (!event.isGuest() && event.getClanId() == ClanID.CLAN && event.getClanChannel() != null)
		{
			clanRankReporter.reportNow();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (TriglavConfig.GROUP.equals(event.getGroup()) && "clanCode".equals(event.getKey()))
		{
			keyStore.refresh(result -> onLinkResult(result, true));
		}

		if (TriglavConfig.GROUP.equals(event.getGroup()) && "shareLocationDanger".equals(event.getKey()))
		{
			// Ticking it off must withdraw a position that was sent from a dangerous area right away.
			locationSharer.clear();
		}

		if (TriglavConfig.GROUP.equals(event.getGroup()) && "shareLocation".equals(event.getKey()))
		{
			if (config.shareLocation())
			{
				chat("TRIGLAV: lokacija se deli s clani klana (zemljevid v zivo). Izklopis jo v nastavitvah plugina; v Wildernessu in raidih se ne posilja.");
			}
			else
			{
				locationSharer.clear();
			}
		}
	}

	/** Panel "Poveži": storing the code fires ConfigChanged, which does the actual linking. */
	private void linkCode(String code)
	{
		if (code.isEmpty())
		{
			chat("TRIGLAV: vpiši svojo kodo s profila na clan.kokalj.dev (TRG-XXXX).");
			return;
		}

		if (code.equals(config.clanCode()))
		{
			keyStore.refresh(result -> onLinkResult(result, true));
		}
		else
		{
			configManager.setConfiguration(TriglavConfig.GROUP, "clanCode", code);
		}
	}

	/** @param announce true when the member just typed a code, false for the quiet check at startup */
	private void onLinkResult(KeyStore.Result result, boolean announce)
	{
		panel.showLinked(keyStore.isLinked(), keyStore.linkedName());
		panel.showOverview(overviewClient.current(), keyStore.isLinked());

		switch (result)
		{
			case LINKED:
				configClient.refreshNow();
				overviewClient.refreshNow();
				if (announce && client.getGameState() == GameState.LOGGED_IN)
				{
					// Linked mid-session: the login snapshot went nowhere without a key, so send it now.
					loginPending = true;
				}
				if (announce)
				{
					chat("TRIGLAV: povezano" + (keyStore.linkedName() == null ? "." : " kot " + keyStore.linkedName() + "."));
				}
				break;
			case WRONG_CODE:
				chat("TRIGLAV: koda ne velja. Preveri jo na clan.kokalj.dev/profil (Pokaži mojo kodo).");
				break;
			case UNREACHABLE:
				if (announce)
				{
					chat("TRIGLAV: stran trenutno ni dosegljiva, poskusi čez nekaj minut.");
				}
				break;
			default:
				break;
		}
	}

	/** Panel button: screenshot plus the member's line, posted to the clan's Discord by the site. */
	private void shareWithClan(String text)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			chat("TRIGLAV: prijavi se v igro, da lahko posljes posnetek.");
			return;
		}

		captureScreenshot(png -> shareClient.share(text, png, result -> chat("TRIGLAV: " + result)));
	}

	/** Panel button: post an LFG from the game, optionally with the current setup as its recommended gear. */
	private void createLfg(String activity, String title, int inMinutes, int capacity, boolean attachSetup, String placeName)
	{
		if (!keyStore.isLinked())
		{
			chat("TRIGLAV: najprej poveži račun.");
			return;
		}

		final java.util.function.Consumer<String> done = result -> chat("TRIGLAV: " + result);

		// Position and setup are read on the client thread, then the request goes out.
		clientThread.invoke(() ->
		{
			LfgClient.Place place = null;
			if (placeName != null && client.getLocalPlayer() != null)
			{
				final net.runelite.api.coords.WorldPoint here = client.getLocalPlayer().getWorldLocation();
				place = new LfgClient.Place(here.getX(), here.getY(), here.getPlane(), placeName);
			}

			final LfgClient.Place spot = place;
			if (attachSetup)
			{
				gearClient.captureSetup(title, setup -> lfgClient.create(activity, title, inMinutes, capacity, setup, spot, done));
			}
			else
			{
				lfgClient.create(activity, title, inMinutes, capacity, null, spot, done);
			}
		});
	}

	/** Panel button: compare what is carried with the setup of the next joined LFG. */
	private void checkLfgGear()
	{
		clientThread.invoke(() ->
		{
			final com.triglav.clan.overview.Overview.MyLfg next = lfgReminder.nextWithGear();
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				chat("TRIGLAV: prijavi se v igro.");
			}
			else if (next == null)
			{
				chat("TRIGLAV: nimas LFG-ja s priporocenim setupom.");
			}
			else
			{
				lfgReminder.checkGear(next, message -> chat("TRIGLAV: " + message));
			}
		});
	}

	private void showFeedMessage(String text)
	{
		chat("TRIGLAV: " + text);
	}

	/**
	 * The frame only exists once the next one is drawn; if that never happens (minimised window)
	 * the event still ships, just without a screenshot.
	 */
	private void captureScreenshot(Consumer<byte[]> onCaptured)
	{
		final AtomicBoolean done = new AtomicBoolean();

		drawManager.requestNextFrameListener(image ->
		{
			if (!done.compareAndSet(false, true))
			{
				return;
			}

			final BufferedImage buffered = ImageUtil.bufferedImageFromImage(image);
			executor.execute(() ->
			{
				try
				{
					onCaptured.accept(Screenshot.encode(buffered));
				}
				catch (IOException e)
				{
					log.warn("Could not encode screenshot", e);
					onCaptured.accept(null);
				}
			});
		});

		executor.schedule(() ->
		{
			if (done.compareAndSet(false, true))
			{
				onCaptured.accept(null);
			}
		}, SCREENSHOT_TIMEOUT_SECONDS, TimeUnit.SECONDS);
	}

	private void chat(String message)
	{
		final String text = GameText.ascii(message);
		clientThread.invoke(() -> client.addChatMessage(ChatMessageType.CONSOLE, "", text, null));
	}
}

package com.triglav.clan.bingo;

import java.awt.Color;
import java.util.List;

/** Immutable snapshot of GET /api/plugin/bingo/:key for the member's team. */
public final class BingoBoard
{
	public enum Status
	{
		OPEN, PENDING, DONE
	}

	public static final class Tile
	{
		public final int index;
		public final String title;
		public final int points;
		public final int iconItemId;
		public final int[] itemIds;
		public final Status status;

		public Tile(int index, String title, int points, int iconItemId, int[] itemIds, Status status)
		{
			this.index = index;
			this.title = title;
			this.points = points;
			this.iconItemId = iconItemId;
			this.itemIds = itemIds;
			this.status = status;
		}

		/** @return the tile's icon, else its first item, else -1 (the overlay then shows initials) */
		public int displayItemId()
		{
			if (iconItemId > 0)
			{
				return iconItemId;
			}
			return itemIds.length > 0 ? itemIds[0] : -1;
		}
	}

	public final String title;
	public final int rows;
	public final int cols;
	public final String teamName;
	public final Color teamColor;
	public final List<Tile> tiles;

	public BingoBoard(String title, int rows, int cols, String teamName, Color teamColor, List<Tile> tiles)
	{
		this.title = title;
		this.rows = rows;
		this.cols = cols;
		this.teamName = teamName;
		this.teamColor = teamColor;
		this.tiles = tiles;
	}

	/** @return true if some tile this team hasn't finished yet would be completed by this item */
	public boolean hasOpenTileFor(int itemId)
	{
		for (Tile tile : tiles)
		{
			if (tile.status == Status.DONE)
			{
				continue;
			}
			for (int id : tile.itemIds)
			{
				if (id == itemId)
				{
					return true;
				}
			}
		}
		return false;
	}
}

package com.triglav.clan.bingo;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.triglav.clan.TriglavConfig;
import com.triglav.clan.net.ApiClient;
import com.triglav.clan.net.KeyStore;
import java.awt.Color;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Polls GET /api/plugin/bingo/:key (docs/plugin-brief.md §5.3) for the member's team board. The
 * site completes tiles itself from LOOT events, so after a drop that matches an open tile the
 * plugin just asks again a few seconds later instead of guessing the tile state locally.
 */
@Slf4j
@Singleton
public class BingoClient
{
	private static final int POLL_SECONDS = 60;
	private static final int REFRESH_AFTER_DROP_SECONDS = 10;
	private static final Color DEFAULT_TEAM_COLOR = new Color(0xd8a93f);

	private final OkHttpClient httpClient;
	private final TriglavConfig config;
	private final KeyStore keyStore;
	private final ScheduledExecutorService executor;
	private final AtomicReference<BingoBoard> board = new AtomicReference<>();
	private volatile Consumer<String> announcer = message ->
	{
	};

	@Inject
	private BingoClient(OkHttpClient httpClient, TriglavConfig config, KeyStore keyStore, ScheduledExecutorService executor)
	{
		this.httpClient = httpClient;
		this.config = config;
		this.keyStore = keyStore;
		this.executor = executor;
		executor.scheduleWithFixedDelay(this::refresh, 5, POLL_SECONDS, TimeUnit.SECONDS);
	}

	/** Told when a tile turns confirmed, so a drop is acknowledged in the game chat within seconds. */
	public void setAnnouncer(Consumer<String> announcer)
	{
		this.announcer = announcer;
	}

	/** @return the current board, or null if there is no active bingo for this member */
	public BingoBoard board()
	{
		return board.get();
	}

	public void refreshSoon()
	{
		executor.schedule(this::refresh, REFRESH_AFTER_DROP_SECONDS, TimeUnit.SECONDS);
	}

	private void refresh()
	{
		final String clanCode = keyStore.ingestKey();
		if (clanCode == null || !config.bingoOverlay())
		{
			board.set(null);
			return;
		}

		final HttpUrl url = HttpUrl.parse(ApiClient.siteUrl() + "/api/plugin/bingo/" + clanCode);
		if (url == null)
		{
			return;
		}

		try (Response response = httpClient.newCall(new Request.Builder().url(url).build()).execute())
		{
			if (!response.isSuccessful() || response.body() == null)
			{
				return;
			}
			final BingoBoard fresh = parse(new JsonParser().parse(response.body().string()).getAsJsonObject());
			announceNewlyDone(board.getAndSet(fresh), fresh);
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Bingo poll failed: {}", e.getMessage());
		}
	}

	private void announceNewlyDone(BingoBoard before, BingoBoard after)
	{
		for (String message : newlyDone(before, after))
		{
			announcer.accept(message);
		}
	}

	/** Only between two boards of the same bingo: the first load after login must not announce old progress. */
	static List<String> newlyDone(BingoBoard before, BingoBoard after)
	{
		final List<String> messages = new ArrayList<>();
		if (before == null || after == null || !before.title.equals(after.title))
		{
			return messages;
		}

		for (BingoBoard.Tile tile : after.tiles)
		{
			if (tile.status != BingoBoard.Status.DONE)
			{
				continue;
			}

			for (BingoBoard.Tile old : before.tiles)
			{
				if (old.index == tile.index && old.status != BingoBoard.Status.DONE)
				{
					messages.add("Bingo: ploščica »" + tile.title + "« je potrjena" + (tile.points > 0 ? " (+" + tile.points + " točk za ekipo)." : "."));
				}
			}
		}
		return messages;
	}

	static BingoBoard parse(JsonObject body)
	{
		if (!body.has("bingo") || body.get("bingo").isJsonNull())
		{
			return null;
		}

		final JsonObject bingo = body.getAsJsonObject("bingo");
		final JsonObject team = body.has("team") && !body.get("team").isJsonNull() ? body.getAsJsonObject("team") : null;

		final List<BingoBoard.Tile> tiles = new ArrayList<>();
		final JsonArray rawTiles = body.has("tiles") ? body.getAsJsonArray("tiles") : new JsonArray();
		for (JsonElement element : rawTiles)
		{
			final JsonObject t = element.getAsJsonObject();
			final JsonArray rawIds = t.has("itemIds") && t.get("itemIds").isJsonArray() ? t.getAsJsonArray("itemIds") : new JsonArray();
			final int[] itemIds = new int[rawIds.size()];
			for (int i = 0; i < itemIds.length; i++)
			{
				itemIds[i] = rawIds.get(i).getAsInt();
			}

			tiles.add(new BingoBoard.Tile(
				t.get("index").getAsInt(),
				t.has("title") ? t.get("title").getAsString() : "",
				t.has("points") && !t.get("points").isJsonNull() ? t.get("points").getAsInt() : 0,
				t.has("iconItemId") && !t.get("iconItemId").isJsonNull() ? t.get("iconItemId").getAsInt() : -1,
				itemIds,
				status(t.has("status") ? t.get("status").getAsString() : "open")));
		}

		return new BingoBoard(
			bingo.has("title") ? bingo.get("title").getAsString() : "Bingo",
			bingo.get("rows").getAsInt(),
			bingo.get("cols").getAsInt(),
			team != null && team.has("name") ? team.get("name").getAsString() : "",
			team != null && team.has("color") ? color(team.get("color").getAsString()) : DEFAULT_TEAM_COLOR,
			tiles);
	}

	private static BingoBoard.Status status(String raw)
	{
		switch (raw)
		{
			case "done":
				return BingoBoard.Status.DONE;
			case "pending":
				return BingoBoard.Status.PENDING;
			default:
				return BingoBoard.Status.OPEN;
		}
	}

	private static Color color(String hex)
	{
		try
		{
			return Color.decode(hex);
		}
		catch (NumberFormatException e)
		{
			return DEFAULT_TEAM_COLOR;
		}
	}
}

package com.triglav.clan.bingo;

import com.triglav.clan.TriglavConfig;
import com.triglav.clan.util.GameText;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * The team's bingo board in game (docs/plugin-brief.md §5.3): one square per tile with the
 * tile's item icon, green once the site has approved it, yellow while a proof waits for staff.
 * A tile without any item shows the initials of its title. Hovering a tile shows its title,
 * points and state. Movable like any overlay (Alt+drag).
 */
public class BingoOverlay extends Overlay
{
	private static final int TILE = 30;
	private static final int GAP = 2;
	private static final int HEADER = 16;
	private static final Color OPEN = new Color(30, 34, 45, 200);
	private static final Color PENDING = new Color(216, 169, 63, 170);
	private static final Color DONE = new Color(60, 160, 90, 190);

	private final BingoClient bingoClient;
	private final ItemManager itemManager;
	private final TriglavConfig config;
	private final Client client;
	private final TooltipManager tooltipManager;

	@Inject
	private BingoOverlay(BingoClient bingoClient, ItemManager itemManager, TriglavConfig config, Client client, TooltipManager tooltipManager)
	{
		this.bingoClient = bingoClient;
		this.itemManager = itemManager;
		this.config = config;
		this.client = client;
		this.tooltipManager = tooltipManager;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		final BingoBoard board = bingoClient.board();
		if (!config.bingoOverlay() || board == null || board.rows <= 0 || board.cols <= 0)
		{
			return null;
		}

		g.setFont(FontManager.getRunescapeSmallFont());
		final FontMetrics metrics = g.getFontMetrics();
		final String header = GameText.ascii(board.teamName.isEmpty() ? board.title : board.title + " - " + board.teamName);
		final int width = Math.max(board.cols * (TILE + GAP) - GAP, metrics.stringWidth(header));
		final int height = HEADER + board.rows * (TILE + GAP) - GAP;

		g.setColor(board.teamColor);
		g.drawString(header, 0, metrics.getAscent());

		final Point mouse = client.getMouseCanvasPosition();
		final Rectangle bounds = getBounds();
		BingoBoard.Tile hovered = null;

		for (BingoBoard.Tile tile : board.tiles)
		{
			final int row = tile.index / board.cols;
			final int col = tile.index % board.cols;
			if (row >= board.rows)
			{
				continue;
			}

			final int x = col * (TILE + GAP);
			final int y = HEADER + row * (TILE + GAP);

			g.setColor(tile.status == BingoBoard.Status.DONE ? DONE : tile.status == BingoBoard.Status.PENDING ? PENDING : OPEN);
			g.fillRect(x, y, TILE, TILE);

			final int itemId = tile.displayItemId();
			final BufferedImage icon = itemId > 0 ? itemManager.getImage(itemId) : null;
			if (icon != null)
			{
				g.drawImage(icon, x + (TILE - 24) / 2, y + (TILE - 22) / 2, 24, 22, null);
			}
			else
			{
				final String initials = initials(tile.title);
				g.setColor(Color.WHITE);
				g.drawString(initials, x + (TILE - metrics.stringWidth(initials)) / 2, y + (TILE + metrics.getAscent()) / 2 - 1);
			}

			if (mouse != null && bounds != null && new Rectangle(bounds.x + x, bounds.y + y, TILE, TILE).contains(mouse.getX(), mouse.getY()))
			{
				hovered = tile;
			}
		}

		if (hovered != null)
		{
			tooltipManager.add(new Tooltip(GameText.ascii(hovered.title) + "</br>" + hovered.points + " bingo točk za ekipo - " + statusLabel(hovered.status)));
		}

		return new Dimension(width, height);
	}

	/** "Boss pet" -> "BP", "Hard clue unique" -> "HC", "Pet" -> "PE" */
	static String initials(String title)
	{
		final String[] words = GameText.ascii(title).trim().split("\\s+");
		if (words.length >= 2)
		{
			return (words[0].substring(0, 1) + words[1].substring(0, 1)).toUpperCase();
		}
		final String word = words[0];
		return word.isEmpty() ? "?" : word.substring(0, Math.min(2, word.length())).toUpperCase();
	}

	private static String statusLabel(BingoBoard.Status status)
	{
		switch (status)
		{
			case DONE:
				return "potrjeno";
			case PENDING:
				return "caka na pregled";
			default:
				return "odprto";
		}
	}
}

package com.triglav.clan.collect;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.triglav.clan.net.ApiClient;
import com.triglav.clan.net.KeyStore;
import java.io.IOException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.clan.ClanMember;
import net.runelite.api.clan.ClanTitle;
import net.runelite.api.clan.ClanID;
import net.runelite.api.clan.ClanSettings;
import net.runelite.client.callback.ClientThread;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Reads the in-game clan tab and reports ranks to the site (docs/plugin-brief.md §5.1), so
 * leadership stops retyping ranks by hand. Runs on login and every 30 minutes; reading the
 * channel itself must happen on the client thread, sending it must not.
 */
@Slf4j
@Singleton
public class ClanRankReporter
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final long INTERVAL_MINUTES = 30;

	private final Client client;
	private final ClientThread clientThread;
	private final OkHttpClient httpClient;
	private final KeyStore keyStore;

	@Inject
	private ClanRankReporter(Client client, ClientThread clientThread, OkHttpClient httpClient, KeyStore keyStore, ScheduledExecutorService executor)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.httpClient = httpClient;
		this.keyStore = keyStore;
		executor.scheduleWithFixedDelay(this::reportNow, INTERVAL_MINUTES, INTERVAL_MINUTES, TimeUnit.MINUTES);
	}

	public void reportNow()
	{
		clientThread.invokeLater(() ->
		{
			final JsonArray members = readMembers();
			if (members != null && members.size() > 0)
			{
				send(members);
			}
			else
			{
				log.debug("Clan rank report skipped: clan channel not loaded or empty");
			}
		});
	}

	/**
	 * The full roster comes from the clan settings; the clan channel only lists members who are
	 * online right now (the first live test reported 11 of the clan's ~50).
	 */
	private JsonArray readMembers()
	{
		final ClanSettings settings = client.getClanSettings(ClanID.CLAN);
		if (settings == null)
		{
			return null;
		}

		final JsonArray members = new JsonArray();
		for (ClanMember member : settings.getMembers())
		{
			final ClanTitle title = member.getRank() == null ? null : settings.titleForRank(member.getRank());
			if (member.getName() == null || title == null)
			{
				continue;
			}

			final JsonObject json = new JsonObject();
			json.addProperty("rsn", member.getName());
			json.addProperty("rank", title.getName());
			json.addProperty("rankIndex", member.getRank().getRank());
			members.add(json);
		}
		return members;
	}

	private void send(JsonArray members)
	{
		final String clanCode = keyStore.ingestKey();
		if (clanCode == null)
		{
			return;
		}

		final JsonObject payload = new JsonObject();
		payload.addProperty("ingestKey", clanCode);
		payload.add("members", members);

		final HttpUrl url = HttpUrl.parse(ApiClient.siteUrl() + "/api/plugin/clan");
		if (url == null)
		{
			return;
		}

		final Request request = new Request.Builder().url(url).post(RequestBody.create(JSON, payload.toString())).build();
		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Clan rank report failed: {}", e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				if (!response.isSuccessful())
				{
					log.warn("Clan rank report rejected with HTTP {}", response.code());
				}
				else
				{
					log.debug("Clan rank report sent: {} members", members.size());
				}
				response.close();
			}
		});
	}
}

package com.triglav.clan.collect;

import com.google.gson.JsonObject;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.util.Text;

/**
 * "You have completed 80 Master Treasure Trails." - the count and tier of a finished clue.
 * The casket's contents are not read here: they arrive as a normal loot event (LootReceived with
 * type EVENT) and go to the site as LOOT, so the drop feed shows them without any double counting.
 */
public final class ClueChat
{
	private static final Pattern COMPLETED = Pattern.compile(
		"You have completed (?<count>[\\d,]+) (?<tier>\\w+) Treasure Trails?\\.");

	private ClueChat()
	{
	}

	/** @return the CLUE `extra` payload, or null if this message isn't a completed clue */
	public static JsonObject parse(ChatMessage event)
	{
		final Matcher matcher = COMPLETED.matcher(Text.removeTags(event.getMessage()));
		if (!matcher.find())
		{
			return null;
		}

		final JsonObject extra = new JsonObject();
		extra.addProperty("clueType", matcher.group("tier"));
		extra.addProperty("numberCompleted", Integer.parseInt(matcher.group("count").replace(",", "")));
		return extra;
	}
}

package com.triglav.clan.collect;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.util.Text;

/**
 * "New item added to your collection log: X" is the stable game message for a new unlock. It
 * carries no counts, only the item name - the site only needs `itemName` to record the
 * achievement (src/lib/achievements.ts, COLLECTION case), so that is all this sends.
 */
public final class CollectionLogChat
{
	private static final Pattern NEW_ITEM = Pattern.compile("New item added to your collection log: (.+)", Pattern.CASE_INSENSITIVE);

	private CollectionLogChat()
	{
	}

	/** @return the unlocked item's name, or null if this message isn't a collection log unlock */
	public static String newItemName(ChatMessage event)
	{
		final Matcher matcher = NEW_ITEM.matcher(Text.removeTags(event.getMessage()));
		return matcher.find() ? matcher.group(1).trim() : null;
	}
}

package com.triglav.clan.collect;

import com.google.gson.JsonObject;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarPlayerID;

/**
 * Collection log progress straight from the two varps the log's own header uses, so no widget has
 * to be open. They read 0 until the client has them, in which case nothing is reported - a wrong
 * total would skew the site's rank recommendations, a missing one just leaves the old value.
 */
public final class CollectionLogTotals
{
	private CollectionLogTotals()
	{
	}

	public static int completed(Client client)
	{
		return client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
	}

	public static int total(Client client)
	{
		return client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);
	}

	/** @return {completed,total} in the shape of the site's LOGIN snapshot, or null while unknown */
	public static JsonObject snapshot(Client client)
	{
		final int completed = completed(client);
		final int total = total(client);
		if (completed <= 0 || total <= 0 || completed > total)
		{
			return null;
		}

		final JsonObject progress = new JsonObject();
		progress.addProperty("completed", completed);
		progress.addProperty("total", total);
		return progress;
	}
}

package com.triglav.clan.collect;

import com.google.gson.JsonObject;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;

/**
 * Combat achievements from the completion message, with the point totals read from varbits
 * (site: `currentTier` keeps Account.caTier in sync for rank recommendations, `justCompletedTier`
 * raises the milestone). Per-task events carry no milestone on their own, so they cost nothing
 * beyond one stored event.
 */
@Singleton
public class CombatTaskTracker
{
	private static final Pattern TASK = Pattern.compile(
		"Congratulations, you've completed an? (?<tier>\\w+) combat task: (?<task>.+?)\\.");
	private static final Pattern POINTS_SUFFIX = Pattern.compile("\\s*\\(\\d+ points?\\)$");

	private static final String[] TIERS = {"EASY", "MEDIUM", "HARD", "ELITE", "MASTER", "GRANDMASTER"};

	/** Tasks completed per tier. */
	private static final int[] COMPLETED_VARBITS = {
		VarbitID.CA_TOTAL_TASKS_COMPLETED_EASY, VarbitID.CA_TOTAL_TASKS_COMPLETED_MEDIUM,
		VarbitID.CA_TOTAL_TASKS_COMPLETED_HARD, VarbitID.CA_TOTAL_TASKS_COMPLETED_ELITE,
		VarbitID.CA_TOTAL_TASKS_COMPLETED_MASTER, VarbitID.CA_TOTAL_TASKS_COMPLETED_GRANDMASTER,
	};

	/** Cumulative points that unlock each tier's rewards; 0 until the client has them. */
	private static final int[] THRESHOLD_VARBITS = {
		VarbitID.CA_THRESHOLD_EASY, VarbitID.CA_THRESHOLD_MEDIUM, VarbitID.CA_THRESHOLD_HARD,
		VarbitID.CA_THRESHOLD_ELITE, VarbitID.CA_THRESHOLD_MASTER, VarbitID.CA_THRESHOLD_GRANDMASTER,
	};

	/** Points a single task of each tier is worth. */
	private static final int[] TIER_POINTS = {1, 2, 3, 4, 5, 6};

	/**
	 * @return the COMBAT_ACHIEVEMENT `extra` payload, or null when the message is something else.
	 * Reads varbits, so it must run on the client thread, one tick after the message (the client
	 * has not applied the new totals yet while the message itself is being handled).
	 */
	public JsonObject parse(Client client, String message)
	{
		final Matcher matcher = TASK.matcher(message);
		if (!matcher.find())
		{
			return null;
		}

		final int tierIndex = indexOfTier(matcher.group("tier"));
		if (tierIndex < 0)
		{
			return null;
		}

		final JsonObject extra = new JsonObject();
		extra.addProperty("tier", TIERS[tierIndex]);
		extra.addProperty("task", POINTS_SUFFIX.matcher(matcher.group("task")).replaceFirst(""));

		final int totalPoints = totalPoints(client);
		extra.addProperty("totalPoints", totalPoints);

		final String current = tierFor(client, totalPoints);
		if (current != null)
		{
			extra.addProperty("currentTier", current);

			// The same task that pushed us over a reward threshold is the one that completed the tier.
			final String before = tierFor(client, totalPoints - TIER_POINTS[tierIndex]);
			if (!current.equals(before))
			{
				extra.addProperty("justCompletedTier", current);
			}
		}

		return extra;
	}

	private static int indexOfTier(String name)
	{
		for (int i = 0; i < TIERS.length; i++)
		{
			if (TIERS[i].equalsIgnoreCase(name))
			{
				return i;
			}
		}
		return -1;
	}

	private int totalPoints(Client client)
	{
		int total = 0;
		for (int i = 0; i < TIERS.length; i++)
		{
			total += client.getVarbitValue(COMPLETED_VARBITS[i]) * TIER_POINTS[i];
		}
		return total;
	}

	/** @return the highest tier whose reward threshold these points reach, or null if unknown */
	private String tierFor(Client client, int points)
	{
		String tier = null;
		for (int i = 0; i < TIERS.length; i++)
		{
			final int threshold = client.getVarbitValue(THRESHOLD_VARBITS[i]);
			if (threshold > 0 && points >= threshold)
			{
				tier = TIERS[i];
			}
		}
		return tier;
	}
}

package com.triglav.clan.collect;

import com.google.gson.JsonObject;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.client.game.ItemManager;

/**
 * Approximates DEATH's `valueLost` (site: lestvica smrti) from the equipment+inventory GE value
 * right before and a few ticks after death, once the game has actually removed what was lost.
 * This is the same technique community death-value trackers use; it is an approximation, not
 * exact OSRS death mechanics (protected items, wilderness skull state, PvP looting by the killer
 * are not modelled individually - they just show up as "how much less you're carrying now").
 * `isPvp`/`killerName` come from who the local player was interacting with at the moment of death,
 * which misses deaths from something you were not targeting (poison, ranged from an unseen enemy) -
 * in that case this reports isPvp=false rather than guessing, since a false PvP flag is more
 * visible and more wrong than an unflagged one (site surfaces PvP deaths specially).
 */
@Singleton
public class DeathTracker
{
	private static final int AFTER_DEATH_DELAY_TICKS = 3;

	private final ItemManager itemManager;
	private int ticksUntilCheck;
	private long valueBeforeDeath;
	private boolean pvpAtDeath;
	private String killerAtDeath;

	@Inject
	private DeathTracker(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	/** Call on ActorDeath once it's confirmed to be the local player. */
	public void onLocalPlayerDied(Client client)
	{
		valueBeforeDeath = containerValue(client);
		ticksUntilCheck = AFTER_DEATH_DELAY_TICKS;

		final Actor interacting = client.getLocalPlayer().getInteracting();
		pvpAtDeath = interacting instanceof Player;
		killerAtDeath = pvpAtDeath ? interacting.getName() : null;
	}

	/** @return the DEATH `extra` payload once ready, or null if still waiting / nothing pending */
	public JsonObject onGameTick(Client client)
	{
		if (ticksUntilCheck <= 0)
		{
			return null;
		}

		if (--ticksUntilCheck > 0)
		{
			return null;
		}

		final long lost = Math.max(0, valueBeforeDeath - containerValue(client));
		final JsonObject extra = new JsonObject();
		extra.addProperty("valueLost", lost);
		extra.addProperty("isPvp", pvpAtDeath);
		if (killerAtDeath != null)
		{
			extra.addProperty("killerName", killerAtDeath);
		}
		return extra;
	}

	private long containerValue(Client client)
	{
		return containerValue(client, InventoryID.INVENTORY) + containerValue(client, InventoryID.EQUIPMENT);
	}

	private long containerValue(Client client, InventoryID id)
	{
		final ItemContainer container = client.getItemContainer(id);
		if (container == null)
		{
			return 0;
		}

		long total = 0;
		for (Item item : container.getItems())
		{
			if (item.getId() <= 0)
			{
				continue;
			}
			final int canonicalId = itemManager.canonicalize(item.getId());
			total += (long) itemManager.getItemPrice(canonicalId) * item.getQuantity();
		}
		return total;
	}
}

