 * <p>
 * This is tier-level completion, not the per-task breakdown (`achievementDiaryTasks` in the site's
 * type) — task-level state has no equivalent varbit family (see DECISIONS.md).
 */
public final class DiarySnapshot
{
	private static final int[] TIER_IDS = {
		Varbits.DIARY_ARDOUGNE_EASY, Varbits.DIARY_ARDOUGNE_MEDIUM, Varbits.DIARY_ARDOUGNE_HARD, Varbits.DIARY_ARDOUGNE_ELITE,
		Varbits.DIARY_DESERT_EASY, Varbits.DIARY_DESERT_MEDIUM, Varbits.DIARY_DESERT_HARD, Varbits.DIARY_DESERT_ELITE,
		Varbits.DIARY_FALADOR_EASY, Varbits.DIARY_FALADOR_MEDIUM, Varbits.DIARY_FALADOR_HARD, Varbits.DIARY_FALADOR_ELITE,
		Varbits.DIARY_FREMENNIK_EASY, Varbits.DIARY_FREMENNIK_MEDIUM, Varbits.DIARY_FREMENNIK_HARD, Varbits.DIARY_FREMENNIK_ELITE,
		Varbits.DIARY_KANDARIN_EASY, Varbits.DIARY_KANDARIN_MEDIUM, Varbits.DIARY_KANDARIN_HARD, Varbits.DIARY_KANDARIN_ELITE,
		Varbits.DIARY_KARAMJA_EASY, Varbits.DIARY_KARAMJA_MEDIUM, Varbits.DIARY_KARAMJA_HARD, Varbits.DIARY_KARAMJA_ELITE,
		Varbits.DIARY_KOUREND_EASY, Varbits.DIARY_KOUREND_MEDIUM, Varbits.DIARY_KOUREND_HARD, Varbits.DIARY_KOUREND_ELITE,
		Varbits.DIARY_LUMBRIDGE_EASY, Varbits.DIARY_LUMBRIDGE_MEDIUM, Varbits.DIARY_LUMBRIDGE_HARD, Varbits.DIARY_LUMBRIDGE_ELITE,
		Varbits.DIARY_MORYTANIA_EASY, Varbits.DIARY_MORYTANIA_MEDIUM, Varbits.DIARY_MORYTANIA_HARD, Varbits.DIARY_MORYTANIA_ELITE,
		Varbits.DIARY_VARROCK_EASY, Varbits.DIARY_VARROCK_MEDIUM, Varbits.DIARY_VARROCK_HARD, Varbits.DIARY_VARROCK_ELITE,
		Varbits.DIARY_WESTERN_EASY, Varbits.DIARY_WESTERN_MEDIUM, Varbits.DIARY_WESTERN_HARD, Varbits.DIARY_WESTERN_ELITE,
		Varbits.DIARY_WILDERNESS_EASY, Varbits.DIARY_WILDERNESS_MEDIUM, Varbits.DIARY_WILDERNESS_HARD, Varbits.DIARY_WILDERNESS_ELITE,
	};

	private DiarySnapshot()
	{
	}

	public static JsonObject build(Client client)
	{
		int completed = 0;
		for (int id : TIER_IDS)
		{
			if (client.getVarbitValue(id) != 0)
			{
				completed++;
			}
		}

		final JsonObject diary = new JsonObject();
		diary.addProperty("completed", completed);
		diary.addProperty("total", TIER_IDS.length);
		return diary;
	}
}

package com.triglav.clan.collect;

import com.google.gson.JsonObject;
import java.util.concurrent.ConcurrentHashMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Singleton;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.util.Text;

/**
 * Reads the "Your X kill count is: N" and "Fight duration: M:SS. Personal best: M:SS" game
 * messages, the same signals Dink uses - RuneLite has no structured kill count API. The count is
 * both attached to the next LOOT event for that NPC and sent as its own KILL_COUNT event, which
 * the site turns into a boss record (kill count + personal best, src/lib/dink/parse.ts).
 *
 * The two messages arrive on the same tick in either order, so the event is assembled on the game
 * tick after them. A duration without a boss name is dropped after a few ticks rather than kept,
 * so it cannot attach itself to an unrelated kill later on.
 */
@Singleton
public class KillCountTracker
{
	private static final Pattern KILL_COUNT = Pattern.compile(
		"Your (?<boss>.+?) (?:kill|chest|completion|harvest|success|opened|lap) ?count is: ?(?<count>[\\d,]+)\\b",
		Pattern.CASE_INSENSITIVE);
	private static final Pattern KILL_COUNT_ALT = Pattern.compile(
		"Your (?:completed|subdued) (?<boss>.+?) count is: ?(?<count>[\\d,]+)\\b", Pattern.CASE_INSENSITIVE);
	private static final Pattern DURATION = Pattern.compile(
		"(?:Duration|time|Subdued in):? (?<time>[\\d:]+(?:\\.\\d+)?)\\.?(?: Personal best: (?<pb>[\\d:]+(?:\\.\\d+)?))?",
		Pattern.CASE_INSENSITIVE);

	/** A duration with no boss name is forgotten after this many ticks. */
	private static final int MAX_WAITING_TICKS = 10;

	private final ConcurrentHashMap<String, Integer> counts = new ConcurrentHashMap<>();

	private String boss;
	private int count;
	private String time;
	private String personalBest;
	private boolean isPersonalBest;
	private int waitingTicks;

	public void reset()
	{
		boss = null;
		time = null;
		personalBest = null;
		isPersonalBest = false;
		waitingTicks = 0;
	}

	public void onChatMessage(ChatMessage event)
	{
		final String message = Text.removeTags(event.getMessage());

		Matcher matcher = KILL_COUNT.matcher(message);
		boolean found = matcher.find();
		if (!found)
		{
			matcher = KILL_COUNT_ALT.matcher(message);
			found = matcher.find();
		}

		if (found)
		{
			final String name = matcher.group("boss").trim();
			final int value = Integer.parseInt(matcher.group("count").replace(",", ""));
			counts.put(Text.standardize(name), value);
			boss = name;
			count = value;
			return;
		}

		final Matcher duration = DURATION.matcher(message);
		if (duration.find())
		{
			time = iso(duration.group("time"));
			personalBest = iso(duration.group("pb"));
			isPersonalBest = message.toLowerCase().contains("new personal best");
			if (isPersonalBest)
			{
				personalBest = time;
			}
		}
	}

	/** @return the KILL_COUNT `extra` payload once boss and count are known, or null */
	public JsonObject onGameTick()
	{
		if (boss == null)
		{
			if (time != null && ++waitingTicks > MAX_WAITING_TICKS)
			{
				reset();
			}
			return null;
		}

		final JsonObject extra = new JsonObject();
		extra.addProperty("boss", boss);
		extra.addProperty("count", count);
		if (time != null)
		{
			extra.addProperty("time", time);
			extra.addProperty("isPersonalBest", isPersonalBest);
			if (personalBest != null)
			{
				extra.addProperty("personalBest", personalBest);
			}
		}

		reset();
		return extra;
	}

	/** @return the last seen kill count for this NPC name, or -1 if none was seen this session */
	public int lastCount(String npcName)
	{
		return counts.getOrDefault(Text.standardize(npcName), -1);
	}

	/** "1:23.40" / "1:02:03" -> the ISO-8601 duration the site parses (src/lib/dink/parse.ts). */
	private static String iso(String clock)
	{
		if (clock == null || clock.isEmpty())
		{
			return null;
		}

		final String[] parts = clock.split(":");
		if (parts.length < 2 || parts.length > 3)
		{
			return null;
		}

		try
		{
			final int hours = parts.length == 3 ? Integer.parseInt(parts[0]) : 0;
			final int minutes = Integer.parseInt(parts[parts.length - 2]);
			final double seconds = Double.parseDouble(parts[parts.length - 1]);
			final StringBuilder out = new StringBuilder("PT");
			if (hours > 0)
			{
				out.append(hours).append('H');
			}
			if (minutes > 0)
			{
				out.append(minutes).append('M');
			}
			out.append(seconds == Math.floor(seconds) ? String.valueOf((int) seconds) : String.valueOf(seconds)).append('S');
			return out.toString();
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
}

package com.triglav.clan.collect;

import com.google.gson.JsonObject;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;

/**
 * Turns RuneLite's StatChanged into a Dink-shaped LEVEL event (site: src/lib/achievements.ts,
 * which raises a 99 milestone from `levelledSkills` and "maxed" from `allSkills`).
 *
 * StatChanged fires for every skill right after login, so the levels are primed from the client
 * when the LOGIN snapshot goes out and only a later increase counts as a level-up. Two skills can
 * level on the same tick (Hitpoints alongside a combat skill), so they are batched into one event.
 */
@Singleton
public class LevelTracker
{
	private final Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
	private final Map<String, Integer> pending = new LinkedHashMap<>();

	/** Called with the LOGIN snapshot: what we see now is the baseline, not a level-up. */
	public void prime(Client client)
	{
		levels.clear();
		pending.clear();
		for (Skill skill : Skill.values())
		{
			if (skill != Skill.OVERALL)
			{
				levels.put(skill, client.getRealSkillLevel(skill));
			}
		}
	}

	public void reset()
	{
		levels.clear();
		pending.clear();
	}

	public void onStatChanged(StatChanged event)
	{
		final Skill skill = event.getSkill();
		if (skill == Skill.OVERALL)
		{
			return;
		}

		final Integer previous = levels.put(skill, event.getLevel());
		if (previous != null && event.getLevel() > previous)
		{
			pending.put(skill.getName(), event.getLevel());
		}
	}

	/** @return the LEVEL `extra` payload once a level-up is pending, or null */
	public JsonObject onGameTick(Client client)
	{
		if (pending.isEmpty())
		{
			return null;
		}

		final JsonObject levelledSkills = new JsonObject();
		for (Map.Entry<String, Integer> entry : pending.entrySet())
		{
			levelledSkills.addProperty(entry.getKey(), entry.getValue());
		}
		pending.clear();

		final JsonObject allSkills = new JsonObject();
		for (Skill skill : Skill.values())
		{
			if (skill != Skill.OVERALL)
			{
				allSkills.addProperty(skill.getName(), client.getRealSkillLevel(skill));
			}
		}

		final Player local = client.getLocalPlayer();
		final JsonObject combatLevel = new JsonObject();
		combatLevel.addProperty("value", local == null ? 0 : local.getCombatLevel());

		final JsonObject extra = new JsonObject();
		extra.add("levelledSkills", levelledSkills);
		extra.add("allSkills", allSkills);
		extra.add("combatLevel", combatLevel);
		return extra;
	}
}

package com.triglav.clan.collect;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.Collection;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;

/**
 * Builds the `extra` block of a LOOT event (site: docs/plugin-brief.md §2, src/lib/dink/parse.ts).
 * `rarity` and `party` are left out - the site treats both as optional and we have no reliable
 * source for either without the drop-rate tables Dink ships.
 */
@Singleton
public class LootCollector
{
	private final ItemManager itemManager;
	private final KillCountTracker killCountTracker;

	@Inject
	private LootCollector(ItemManager itemManager, KillCountTracker killCountTracker)
	{
		this.itemManager = itemManager;
		this.killCountTracker = killCountTracker;
	}

	public JsonObject build(NpcLootReceived event)
	{
		final String npcName = event.getNpc().getName() == null ? "Unknown" : event.getNpc().getName();
		final JsonObject extra = build(npcName, "NPC", event.getItems());

		final int killCount = killCountTracker.lastCount(npcName);
		if (killCount >= 0)
		{
			extra.addProperty("killCount", killCount);
		}

		return extra;
	}

	/**
	 * Loot that isn't a plain NPC drop: raid chests, clue caskets, implings, pickpocketing.
	 * The site shows these in the drop feed exactly like NPC loot, with `category` telling them apart.
	 */
	public JsonObject build(String source, String category, Collection<ItemStack> stacks)
	{
		final JsonArray items = new JsonArray();
		for (ItemStack stack : stacks)
		{
			final int canonicalId = itemManager.canonicalize(stack.getId());
			final JsonObject item = new JsonObject();
			item.addProperty("id", canonicalId);
			item.addProperty("name", itemManager.getItemComposition(canonicalId).getName());
			item.addProperty("quantity", stack.getQuantity());
			item.addProperty("priceEach", itemManager.getItemPrice(canonicalId));
			items.add(item);
		}

		final JsonObject extra = new JsonObject();
		extra.add("items", items);
		extra.addProperty("source", source == null || source.isEmpty() ? "Unknown" : source);
		extra.addProperty("category", category);
		return extra;
	}
}

package com.triglav.clan.collect;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;

/** Total GE value of a LOOT `extra.items` array, used to decide whether a drop clears the screenshot threshold. */
public final class LootValue
{
	private LootValue()
	{
	}

	public static long total(JsonArray items)
	{
		long total = 0;
		for (JsonElement element : items)
		{
			final JsonObject item = element.getAsJsonObject();
			total += item.get("priceEach").getAsLong() * item.get("quantity").getAsLong();
		}
		return total;
	}
}

package com.triglav.clan.collect;

import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.NpcSpawned;
import net.runelite.client.util.Text;

/**
 * "You have a funny feeling like you're being followed" never carries the pet's name, and there
 * is no reliable API for a full pet inventory (Dink gets that from the Character Summary widget).
 * The name is instead read off whichever NPC spawns next to the player in the few ticks after the
 * message - real OSRS always spawns the new pet right at the player's tile. If nothing spawns
 * close enough in time, nothing is reported: a generic name would collide with every other pet
 * under one achievement key on the site (see DECISIONS.md), which is worse than staying silent.
 */
@Singleton
public class PetDetector
{
	private static final String FUNNY_FEELING = "you have a funny feeling like you're being followed";
	private static final int ARM_TICKS = 5;

	private int armedTicksLeft;

	public void onChatMessage(ChatMessage event)
	{
		if (Text.removeTags(event.getMessage()).toLowerCase().contains(FUNNY_FEELING))
		{
			armedTicksLeft = ARM_TICKS;
		}
	}

	public void onGameTick()
	{
		if (armedTicksLeft > 0)
		{
			armedTicksLeft--;
		}
	}

	/** @return the pet's name if this spawn looks like the pet that was just unlocked, else null */
	public String onNpcSpawned(Client client, NpcSpawned event)
	{
		if (armedTicksLeft <= 0)
		{
			return null;
		}

		final NPC npc = event.getNpc();
		final Player local = client.getLocalPlayer();
		if (npc.getName() == null || local == null)
		{
			return null;
		}

		final WorldPoint npcPoint = npc.getWorldLocation();
		final WorldPoint playerPoint = local.getWorldLocation();
		if (npcPoint == null || playerPoint == null || npcPoint.distanceTo(playerPoint) > 1)
		{
			return null;
		}

		armedTicksLeft = 0;
		return npc.getName();
	}
}

package com.triglav.clan.collect;

import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.WeakHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Hitsplat;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.WorldType;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.kit.KitType;
import net.runelite.client.game.ItemManager;

/**
 * A kill counts as ours when we damaged the player and they died shortly after - the same signal
 * Dink uses, since the game tells no one who landed the last hit. The victim's risk is their worn
 * equipment at that moment, read from their appearance (site: src/lib/dink/parse.ts sums
 * `victimEquipment`).
 *
 * Only the wilderness and real PvP worlds are reported. Safe minigames (Castle Wars, Soul Wars,
 * LMS, PvP Arena) would otherwise flood the clan's PK channel with kills that risked nothing.
 */
@Singleton
public class PlayerKillTracker
{
	/** Worn gear only; HAIR and JAW are appearance kits, never items. */
	private static final KitType[] EQUIPMENT_SLOTS;

	private static final long REPEAT_WINDOW_MILLIS = 5_000;

	static
	{
		final List<KitType> slots = new ArrayList<>();
		for (KitType kit : KitType.values())
		{
			if (kit != KitType.HAIR && kit != KitType.JAW)
			{
				slots.add(kit);
			}
		}
		EQUIPMENT_SLOTS = slots.toArray(new KitType[0]);
	}

	private final ItemManager itemManager;

	/** Weak keys: a player who despawns must not be kept alive by this map. */
	private final Map<Player, Integer> damaged = new WeakHashMap<>(4);
	private final Map<String, Long> recentlyReported = new HashMap<>(4);

	@Inject
	private PlayerKillTracker(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	public void reset()
	{
		damaged.clear();
		recentlyReported.clear();
	}

	public void onHitsplat(Client client, HitsplatApplied event)
	{
		final Hitsplat hitsplat = event.getHitsplat();
		if (hitsplat.getAmount() <= 0 || !hitsplat.isMine())
		{
			return;
		}

		final Actor actor = event.getActor();
		if (!(actor instanceof Player) || actor == client.getLocalPlayer())
		{
			return;
		}

		damaged.merge((Player) actor, hitsplat.getAmount(), Integer::sum);
	}

	/** @return one PLAYER_KILL `extra` payload per player we damaged who just died, if any */
	public List<JsonObject> onGameTick(Client client)
	{
		if (damaged.isEmpty())
		{
			return null;
		}

		List<JsonObject> kills = null;
		if (isPvpSituation(client))
		{
			final long now = System.currentTimeMillis();
			recentlyReported.values().removeIf(at -> now - at > REPEAT_WINDOW_MILLIS);

			for (Player victim : damaged.keySet())
			{
				final String name = victim.getName();
				// A multi-tick special attack can land after the kill; report each victim once.
				if (!victim.isDead() || name == null || recentlyReported.containsKey(name))
				{
					continue;
				}

				recentlyReported.put(name, now);
				if (kills == null)
				{
					kills = new ArrayList<>(1);
				}
				kills.add(build(client, victim, name));
			}
		}

		damaged.clear();
		return kills;
	}

	private JsonObject build(Client client, Player victim, String name)
	{
		final JsonObject extra = new JsonObject();
		extra.addProperty("victimName", name);
		extra.addProperty("victimCombatLevel", victim.getCombatLevel());
		extra.addProperty("world", client.getWorld());

		final JsonObject equipment = new JsonObject();
		final PlayerComposition appearance = victim.getPlayerComposition();
		if (appearance != null)
		{
			for (KitType slot : EQUIPMENT_SLOTS)
			{
				final int itemId = appearance.getEquipmentId(slot);
				if (itemId < 0)
				{
					continue;
				}

				final int canonicalId = itemManager.canonicalize(itemId);
				final JsonObject item = new JsonObject();
				item.addProperty("id", canonicalId);
				item.addProperty("name", itemManager.getItemComposition(canonicalId).getName());
				item.addProperty("quantity", 1);
				item.addProperty("priceEach", itemManager.getItemPrice(canonicalId));
				equipment.add(slot.name(), item);
			}
		}
		extra.add("victimEquipment", equipment);

		return extra;
	}

	private static boolean isPvpSituation(Client client)
	{
		final Set<WorldType> world = client.getWorldType();
		if (world.contains(WorldType.LAST_MAN_STANDING)
			|| world.contains(WorldType.TOURNAMENT_WORLD)
			|| world.contains(WorldType.PVP_ARENA))
		{
			return false;
		}

		return client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) == 1
			|| world.contains(WorldType.PVP)
			|| world.contains(WorldType.BOUNTY)
			|| world.contains(WorldType.HIGH_RISK)
			|| world.contains(WorldType.DEADMAN);
	}
}

package com.triglav.clan.collect;

import com.google.gson.JsonObject;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

/**
 * The quest completion scroll (interface 153) is the one reliable signal that a quest is done.
 * Its title wording varies ("You have completed The Corsair Curse!", "'One Small Favour'
 * completed!"), so the name is best effort; the counts the site actually uses for the quest cape
 * milestone come from varbits, which are exact.
 */
@Singleton
public class QuestTracker
{
	private static final Pattern COMPLETED_FIRST = Pattern.compile(".*?completed:? '?(?<quest>.+?)'?[!.]?$");
	private static final Pattern COMPLETED_LAST = Pattern.compile("'?(?<quest>.+?)'? (?:quest )?completed[!.]?$", Pattern.CASE_INSENSITIVE);

	public static final int WIDGET_GROUP = InterfaceID.QUESTSCROLL;

	/** Scroll wording that does not follow the usual pattern (same cases Dink special-cases). */
	private static final Map<String, String> RENAMED = Map.of(
		"Lumbridge Cook... again", "Another Cook's Quest",
		"Skrach 'Bone Crusher' Uglogwee", "Skrach Uglogwee");

	/** "You have kind of completed..." is a partial step, not a finished quest. */
	public boolean isPartial(String title)
	{
		return title != null && title.contains("kind of");
	}

	/** @return the quest scroll's title, or null when it isn't loaded */
	public String title(Client client)
	{
		final Widget title = client.getWidget(InterfaceID.Questscroll.QUEST_TITLE);
		return title == null ? null : Text.removeTags(title.getText()).trim();
	}

	/**
	 * @return the QUEST `extra` payload. Reads varbits, so it must run on the client thread one
	 * tick after the widget loads, by which time the client has applied the new counts.
	 */
	public JsonObject build(Client client, String title)
	{
		final JsonObject extra = new JsonObject();

		final String quest = questName(title);
		if (quest != null)
		{
			extra.addProperty("questName", quest);
		}

		final int completedQuests = client.getVarbitValue(VarbitID.QUESTS_COMPLETED_COUNT);
		final int totalQuests = client.getVarbitValue(VarbitID.QUESTS_TOTAL_COUNT);
		if (completedQuests > 0 && totalQuests > 0)
		{
			extra.addProperty("completedQuests", completedQuests);
			extra.addProperty("totalQuests", totalQuests);
		}

		final int questPoints = client.getVarpValue(VarPlayerID.QP);
		final int totalQuestPoints = client.getVarbitValue(VarbitID.QP_MAX);
		if (questPoints > 0 && totalQuestPoints > 0)
		{
			extra.addProperty("questPoints", questPoints);
			extra.addProperty("totalQuestPoints", totalQuestPoints);
		}

		return extra;
	}

	private static String questName(String title)
	{
		if (title == null || title.isEmpty())
		{
			return null;
		}

		final Matcher first = COMPLETED_FIRST.matcher(title);
		final Matcher last = COMPLETED_LAST.matcher(title);
		final String name = first.matches() ? first.group("quest").trim()
			: last.matches() ? last.group("quest").trim() : title;
		return normalise(name, title);
	}

	/** A partial completion ("...kind of...") is not a finished quest; a few titles read differently from the quest name. */
	static String normalise(String name, String scrollTitle)
	{
		return scrollTitle.contains("kind of") ? null : RENAMED.getOrDefault(name, name);
	}
}

package com.triglav.clan.collect;

import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import javax.imageio.ImageIO;

/**
 * Resizes and encodes a captured frame for the ingest endpoint. docs/plugin-brief.md §2 asks for
 * WebP to save bandwidth, but the JDK has no built-in WebP encoder and the site already
 * re-encodes every upload to WebP itself (src/lib/images.ts) - so PNG at the same width cap gets
 * the actual goal (small upload) without a third-party image codec dependency in a plugin that
 * has to pass RuneLite Plugin Hub review.
 */
public final class Screenshot
{
	private static final int MAX_WIDTH = 1600;

	private Screenshot()
	{
	}

	public static byte[] encode(BufferedImage image) throws IOException
	{
		final BufferedImage scaled = image.getWidth() <= MAX_WIDTH ? image : resize(image);
		try (ByteArrayOutputStream out = new ByteArrayOutputStream())
		{
			ImageIO.write(scaled, "png", out);
			return out.toByteArray();
		}
	}

	private static BufferedImage resize(BufferedImage image)
	{
		final int width = MAX_WIDTH;
		final int height = Math.round((float) image.getHeight() * width / image.getWidth());

		final BufferedImage resized = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		final Graphics2D g = resized.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.drawImage(image, 0, 0, width, height, null);
		g.dispose();
		return resized;
	}
}

package com.triglav.clan.collect;

import com.google.gson.JsonObject;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.Skill;

/**
 * Builds the `skills` block of a Dink-style LOGIN snapshot (site: src/lib/dink/snapshot.ts).
 * The site expects virtual levels (up to 127 at 200M xp) per skill and a real, 99-capped
 * total level (max 2376 across every skill, Sailing included).
 */
public final class SkillSnapshot
{
	private SkillSnapshot()
	{
	}

	public static JsonObject build(Client client)
	{
		final JsonObject levels = new JsonObject();
		final JsonObject experience = new JsonObject();
		int totalLevel = 0;

		for (Skill skill : Skill.values())
		{
			if (skill == Skill.OVERALL)
			{
				continue;
			}

			final int xp = client.getSkillExperience(skill);
			totalLevel += client.getRealSkillLevel(skill);
			levels.addProperty(skill.getName(), Experience.getLevelForXp(xp));
			experience.addProperty(skill.getName(), xp);
		}

		final JsonObject skills = new JsonObject();
		skills.add("levels", levels);
		skills.add("experience", experience);
		skills.addProperty("totalLevel", totalLevel);
		skills.addProperty("totalExperience", client.getOverallExperience());
		return skills;
	}
}

package com.triglav.clan.collect;

import com.google.gson.JsonObject;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Singleton;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.util.Text;

/**
 * A finished slayer task arrives as two messages: what was killed ("You have completed your task!
 * You killed 134 Hellhounds.") and, from a slayer master, the running totals ("You've completed
 * 342 tasks and received 15 points, giving you a total of 1,234."). The second one is what the
 * site turns into a task-count milestone, so the first is held until it shows up.
 */
@Singleton
public class SlayerChat
{
	private static final Pattern TASK = Pattern.compile(
		"You have completed your task! You killed (?<task>[\\d,]+ [^.]+)\\..*");
	private static final Pattern TOTALS = Pattern.compile(
		"You've completed (?:at least )?(?<tasks>[\\d,]+) (?:Wilderness |Mortimer )?tasks?"
			+ "(?: and received (?<points>[\\d,]+) points, giving you a total of [\\d,]+"
			+ "| and reached the maximum amount of Slayer points \\((?<maxPoints>[\\d,]+)\\))?");

	private String lastTask = "";

	public void reset()
	{
		lastTask = "";
	}

	/** @return the SLAYER `extra` payload once the totals message lands, or null */
	public JsonObject parse(ChatMessage event)
	{
		final String message = Text.removeTags(event.getMessage());

		final Matcher task = TASK.matcher(message);
		if (task.find())
		{
			lastTask = task.group("task");
			return null;
		}

		final Matcher totals = TOTALS.matcher(message);
		if (!totals.find())
		{
			return null;
		}

		final JsonObject extra = new JsonObject();
		if (!lastTask.isEmpty())
		{
			extra.addProperty("slayerTask", lastTask);
			lastTask = "";
		}
		extra.addProperty("slayerCompleted", totals.group("tasks"));

		final String points = totals.group("points") == null ? totals.group("maxPoints") : totals.group("points");
		extra.addProperty("slayerPoints", points == null ? "0" : points);
		return extra;
	}
}

