package com.triglav.clan.collect;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.EnumMap;
import java.util.Map;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;

/**
 * XP_MILESTONE in Dink's shape: `milestoneAchieved` (skill names), `xpData` (current XP of every
 * skill) and `interval`. The site only puts milestones from 50M XP up on the wall, so the
 * interval is 50M rather than Dink's 5M default - anything smaller would be stored and ignored.
 * Like the level tracker, XP is primed at login so the first StatChanged burst is not a milestone.
 */
@Singleton
public class XpMilestoneTracker
{
	public static final int INTERVAL = 50_000_000;

	private final Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
	private final JsonArray pending = new JsonArray();

	public void prime(Client client)
	{
		xp.clear();
		while (pending.size() > 0)
		{
			pending.remove(0);
		}

		for (Skill skill : Skill.values())
		{
			if (skill != Skill.OVERALL)
			{
				xp.put(skill, client.getSkillExperience(skill));
			}
		}
	}

	public void reset()
	{
		xp.clear();
		while (pending.size() > 0)
		{
			pending.remove(0);
		}
	}

	public void onStatChanged(StatChanged event)
	{
		final Skill skill = event.getSkill();
		if (skill == Skill.OVERALL)
		{
			return;
		}

		final Integer previous = xp.put(skill, event.getXp());
		if (previous != null && event.getXp() / INTERVAL > previous / INTERVAL)
		{
			pending.add(skill.getName());
		}
	}

	/** @return the XP_MILESTONE `extra` payload once a milestone is pending, or null */
	public JsonObject onGameTick()
	{
		if (pending.size() == 0)
		{
			return null;
		}

		final JsonObject xpData = new JsonObject();
		for (Map.Entry<Skill, Integer> entry : xp.entrySet())
		{
			xpData.addProperty(entry.getKey().getName(), entry.getValue());
		}

		final JsonObject extra = new JsonObject();
		extra.add("milestoneAchieved", pending.deepCopy());
		extra.add("xpData", xpData);
		extra.addProperty("interval", INTERVAL);

		while (pending.size() > 0)
		{
			pending.remove(0);
		}
		return extra;
	}
}

package com.triglav.clan.feed;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.triglav.clan.TriglavConfig;
import com.triglav.clan.net.ApiClient;
import com.triglav.clan.net.KeyStore;
import java.io.IOException;
import java.util.LinkedHashSet;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Polls GET /api/plugin/feed/:key every 60s (docs/plugin-brief.md §5.2) and hands new messages
 * to a callback, which the plugin prints to the game chat. Remembers `id`s so a message is
 * never shown twice, bounded so it cannot grow forever across a long session.
 */
@Slf4j
@Singleton
public class FeedClient
{
	private static final int POLL_SECONDS = 60;
	private static final int MAX_SEEN = 500;

	private final OkHttpClient httpClient;
	private final TriglavConfig config;
	private final KeyStore keyStore;
	private final Set<String> seen = new LinkedHashSet<>();

	@Inject
	private FeedClient(OkHttpClient httpClient, TriglavConfig config, KeyStore keyStore, ScheduledExecutorService executor)
	{
		this.httpClient = httpClient;
		this.config = config;
		this.keyStore = keyStore;
		executor.scheduleWithFixedDelay(this::poll, POLL_SECONDS, POLL_SECONDS, TimeUnit.SECONDS);
	}

	/** Set by the plugin once it knows where messages should go. */
	private volatile Consumer<String> sink;

	public void setSink(Consumer<String> sink)
	{
		this.sink = sink;
	}

	private void poll()
	{
		final Consumer<String> currentSink = sink;
		if (currentSink == null || !config.inGameMessages())
		{
			return;
		}

		final String clanCode = keyStore.ingestKey();
		if (clanCode == null)
		{
			return;
		}

		final HttpUrl url = HttpUrl.parse(ApiClient.siteUrl() + "/api/plugin/feed/" + clanCode);
		if (url == null)
		{
			return;
		}

		final Request request = new Request.Builder().url(url).build();
		try (Response response = httpClient.newCall(request).execute())
		{
			if (!response.isSuccessful() || response.body() == null)
			{
				return;
			}

			final JsonObject body = new JsonParser().parse(response.body().string()).getAsJsonObject();
			final JsonArray messages = body.getAsJsonArray("messages");
			if (messages == null)
			{
				return;
			}

			for (int i = 0; i < messages.size(); i++)
			{
				final JsonObject message = messages.get(i).getAsJsonObject();
				final String id = message.get("id").getAsString();
				if (seen.contains(id))
				{
					continue;
				}

				seen.add(id);
				while (seen.size() > MAX_SEEN)
				{
					seen.remove(seen.iterator().next());
				}

				currentSink.accept(message.get("text").getAsString());
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Feed poll failed: {}", e.getMessage());
		}
	}
}

package com.triglav.clan.gear;

import com.google.gson.JsonArray;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.triglav.clan.net.ApiClient;
import com.triglav.clan.net.KeyStore;
import java.io.IOException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Varbits;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * "Pošlji trenutni setup" (docs/plugin-brief.md §5.3): sends worn equipment and inventory to
 * POST /api/plugin/gear in the RuneLite Inventory Setups shape the site already imports
 * (src/lib/gear.ts `fromInventorySetups`: inv[28], eq[14] by EquipmentInventorySlot index,
 * items {id, q, name}). Containers are read on the client thread, the request goes out off it.
 */
@Slf4j
@Singleton
public class GearClient
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final int INVENTORY_SIZE = 28;
	private static final int EQUIPMENT_SIZE = 14;

	private final Client client;
	private final ClientThread clientThread;
	private final ItemManager itemManager;
	private final OkHttpClient httpClient;
	private final KeyStore keyStore;
	private final ScheduledExecutorService executor;

	@Inject
	private GearClient(Client client, ClientThread clientThread, ItemManager itemManager, OkHttpClient httpClient,
		KeyStore keyStore, ScheduledExecutorService executor)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.itemManager = itemManager;
		this.httpClient = httpClient;
		this.keyStore = keyStore;
		this.executor = executor;
	}

	/**
	 * @param onResult receives a human-readable result line for the game chat
	 */
	public void sendCurrentSetup(String title, Consumer<String> onResult)
	{
		sendCurrentSetup(title, false, onResult);
	}

	/** @param auto true for the background upload: the site keeps one record per member and overwrites it */
	public void sendCurrentSetup(String title, boolean auto, Consumer<String> onResult)
	{
		final String clanCode = keyStore.ingestKey();
		if (clanCode == null)
		{
			onResult.accept("najprej poveži račun.");
			return;
		}

		clientThread.invoke(() ->
		{
			final JsonObject setup = buildSetup(title);
			if (setup == null)
			{
				onResult.accept("setupa ni mogoče prebrati — prijavi se v igro.");
				return;
			}

			final JsonObject payload = new JsonObject();
			payload.addProperty("ingestKey", clanCode);
			payload.addProperty("title", title);
			payload.addProperty("auto", auto);
			payload.add("setup", setup);

			executor.execute(() -> post(payload, onResult));
		});
	}

	/** Client thread: the worn gear and inventory in the Inventory Setups shape, or null if not logged in. */
	private JsonObject buildSetup(String title)
	{
		final ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
		final ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
		if (equipment == null && inventory == null)
		{
			return null;
		}

		final JsonObject setup = new JsonObject();
		setup.add("inv", items(inventory, INVENTORY_SIZE));
		setup.add("eq", items(equipment, EQUIPMENT_SIZE));
		setup.addProperty("sb", client.getVarbitValue(Varbits.SPELLBOOK));
		setup.addProperty("name", title);
		return setup;
	}

	/** Hands the current setup (or null when it cannot be read) to the callback, read on the client thread. */
	public void captureSetup(String title, Consumer<JsonObject> onReady)
	{
		clientThread.invoke(() -> onReady.accept(buildSetup(title)));
	}

	private JsonArray items(ItemContainer container, int size)
	{
		final JsonArray out = new JsonArray();
		final Item[] items = container == null ? new Item[0] : container.getItems();
		for (int i = 0; i < size; i++)
		{
			final Item item = i < items.length ? items[i] : null;
			if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
			{
				out.add(JsonNull.INSTANCE);
				continue;
			}

			final JsonObject json = new JsonObject();
			json.addProperty("id", item.getId());
			if (item.getQuantity() > 1)
			{
				json.addProperty("q", item.getQuantity());
			}
			json.addProperty("name", itemManager.getItemComposition(item.getId()).getName());
			out.add(json);
		}
		return out;
	}

	private void post(JsonObject payload, Consumer<String> onResult)
	{
		final HttpUrl url = HttpUrl.parse(ApiClient.siteUrl() + "/api/plugin/gear");
		if (url == null)
		{
			return;
		}

		final Request request = new Request.Builder().url(url).post(RequestBody.create(JSON, payload.toString())).build();
		try (Response response = httpClient.newCall(request).execute())
		{
			if (!response.isSuccessful() || response.body() == null)
			{
				onResult.accept("setupa ni bilo mogoče poslati (HTTP " + response.code() + ").");
				return;
			}

			final JsonObject body = new JsonParser().parse(response.body().string()).getAsJsonObject();
			onResult.accept(body.has("url") ? "setup shranjen: " + body.get("url").getAsString() : "setup shranjen.");
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Could not send gear setup", e);
			onResult.accept("setupa ni bilo mogoče poslati — stran ni dosegljiva.");
		}
	}
}

package com.triglav.clan.lfg;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.triglav.clan.net.ApiClient;
import com.triglav.clan.net.KeyStore;
import java.io.IOException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Posts an LFG from the game: POST /api/plugin/lfg/:key. The start is sent as "in N minutes" so no
 * time zone ever enters the picture; the site posts it to Discord with the join buttons, same as a
 * post made on the website. The optional setup becomes the post's recommended gear.
 */
@Slf4j
@Singleton
public class LfgClient
{
	/** A meeting spot in OSRS tile coordinates. */
	public static final class Place
	{
		public final int x;
		public final int y;
		public final int plane;
		public final String name;

		public Place(int x, int y, int plane, String name)
		{
			this.x = x;
			this.y = y;
			this.plane = plane;
			this.name = name == null ? "" : name;
		}
	}

	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	private final OkHttpClient httpClient;
	private final KeyStore keyStore;
	private final ScheduledExecutorService executor;
	/** The character being played, so the post shows its RSN as the organiser. */
	private volatile String rsn;

	@Inject
	private LfgClient(OkHttpClient httpClient, KeyStore keyStore, ScheduledExecutorService executor)
	{
		this.httpClient = httpClient;
		this.keyStore = keyStore;
		this.executor = executor;
	}

	public void setRsn(String rsn)
	{
		this.rsn = rsn;
	}

	/** @param setup the current gear in Inventory Setups shape, or null to post without a recommended setup */
	public void create(String activity, String title, int inMinutes, int capacity, JsonObject setup, Consumer<String> onResult)
	{
		create(activity, title, inMinutes, capacity, setup, null, onResult);
	}

	/** @param place where the group meets (tile x, y, plane, optional name), or null for no location */
	public void create(String activity, String title, int inMinutes, int capacity, JsonObject setup, Place place, Consumer<String> onResult)
	{
		final String key = keyStore.ingestKey();
		if (key == null)
		{
			onResult.accept("najprej poveži račun.");
			return;
		}

		executor.execute(() ->
		{
			final HttpUrl url = HttpUrl.parse(ApiClient.siteUrl() + "/api/plugin/lfg/" + key);
			if (url == null)
			{
				return;
			}

			final JsonObject body = new JsonObject();
			body.addProperty("activity", activity);
			body.addProperty("title", title);
			body.addProperty("inMinutes", inMinutes);
			body.addProperty("capacity", capacity);
			if (rsn != null)
			{
				body.addProperty("rsn", rsn);
			}
			if (setup != null)
			{
				body.add("setup", setup);
			}
			if (place != null)
			{
				body.addProperty("locX", place.x);
				body.addProperty("locY", place.y);
				body.addProperty("locPlane", place.plane);
				if (!place.name.isEmpty())
				{
					body.addProperty("locName", place.name);
				}
			}

			try (Response response = httpClient.newCall(new Request.Builder().url(url).post(RequestBody.create(JSON, body.toString())).build()).execute())
			{
				final String raw = response.body() == null ? "" : response.body().string();
				final JsonObject json = raw.isEmpty() ? new JsonObject() : new JsonParser().parse(raw).getAsJsonObject();
				if (response.isSuccessful())
				{
					onResult.accept("LFG objavljen" + (json.has("url") ? ": " + json.get("url").getAsString() : "."));
				}
				else
				{
					onResult.accept(json.has("error") ? json.get("error").getAsString() : "LFG ni bil objavljen (HTTP " + response.code() + ").");
				}
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("LFG create failed", e);
				onResult.accept("LFG ni bil objavljen — stran ni dosegljiva.");
			}
		});
	}
}

package com.triglav.clan.net;

import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Talks to the clan site's ingest endpoint, which speaks the same envelope as Dink
 * (see docs/plugin-brief.md §2 in the site repo). Everything queues and drains off the
 * client thread, so a slow or unreachable site never stutters the game.
 */
@Slf4j
@Singleton
public class ApiClient
{
	/**
	 * Overridable with -Dtriglav.siteUrl=http://localhost:3000 for local development against
	 * `docker compose up` in the site repo. Production members never need to touch this.
	 */
	private static final String DEFAULT_SITE_URL = "https://clan.kokalj.dev";

	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	// PNG, not WebP: the JDK has no WebP encoder; the site converts every upload to WebP itself.
	private static final MediaType PNG = MediaType.parse("image/png");

	/** Queue cap from docs/plugin-brief.md §6. */
	private static final int MAX_QUEUE = 200;
	/** Give up on an individual event after this many failed attempts. */
	private static final int MAX_ATTEMPTS = 3;
	private static final int DRAIN_INTERVAL_SECONDS = 5;

	private final OkHttpClient httpClient;
	private final KeyStore keyStore;
	private final Deque<QueuedEvent> queue = new ArrayDeque<>();

	@Inject
	private ApiClient(OkHttpClient httpClient, KeyStore keyStore, ScheduledExecutorService executor)
	{
		this.httpClient = httpClient;
		this.keyStore = keyStore;
		executor.scheduleWithFixedDelay(this::drain, DRAIN_INTERVAL_SECONDS, DRAIN_INTERVAL_SECONDS, TimeUnit.SECONDS);
	}

	public static String siteUrl()
	{
		final String override = System.getProperty("triglav.siteUrl");
		return override == null || override.trim().isEmpty() ? DEFAULT_SITE_URL : override.trim();
	}

	/** @return true once the clan code has been exchanged for an ingest key */
	public boolean isPaired()
	{
		return keyStore.isLinked();
	}

	/**
	 * Queues a Dink-shaped event for delivery. Safe to call from any thread.
	 *
	 * @param screenshot WebP bytes, or null to send without one
	 */
	public synchronized void send(JsonObject envelope, byte[] screenshot)
	{
		if (!isPaired())
		{
			return;
		}

		if (!envelope.has("playerName") || envelope.get("playerName").getAsString().isEmpty())
		{
			log.debug("Not sending {} without a player name", envelope.has("type") ? envelope.get("type").getAsString() : "?");
			return;
		}

		if (queue.size() >= MAX_QUEUE)
		{
			final QueuedEvent dropped = queue.pollFirst();
			log.warn("Ingest queue full, dropping oldest event: {}", dropped == null ? "?" : dropped.type);
		}

		queue.addLast(new QueuedEvent(envelope, screenshot));
	}

	private void drain()
	{
		QueuedEvent event;
		synchronized (this)
		{
			event = queue.pollFirst();
		}

		if (event == null)
		{
			return;
		}

		if (deliver(event))
		{
			return;
		}

		event.attempts++;
		if (event.attempts < MAX_ATTEMPTS)
		{
			synchronized (this)
			{
				queue.addFirst(event);
			}
		}
		else
		{
			log.warn("Giving up on event after {} attempts: {}", event.attempts, event.type);
		}
	}

	private boolean deliver(QueuedEvent event)
	{
		final String key = keyStore.ingestKey();
		if (key == null)
		{
			return false;
		}

		final HttpUrl url = HttpUrl.parse(siteUrl() + "/api/dink/" + key);
		if (url == null)
		{
			log.warn("Invalid site URL, cannot deliver {}", event.type);
			return false;
		}

		final RequestBody body = event.screenshot == null
			? RequestBody.create(JSON, event.json.toString())
			: new MultipartBody.Builder()
				.setType(MultipartBody.FORM)
				.addFormDataPart("payload_json", event.json.toString())
				.addFormDataPart("file", "screenshot.png", RequestBody.create(PNG, event.screenshot))
				.build();

		final Request request = new Request.Builder().url(url).post(body).build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (response.isSuccessful())
			{
				return true;
			}

			final String reason = response.body() == null ? "" : response.body().string();
			log.warn("Ingest rejected {} with HTTP {}: {}", event.type, response.code(),
				reason.length() > 300 ? reason.substring(0, 300) : reason);
			// A 4xx other than 429 means this event itself is invalid; retrying it can't help.
			return response.code() >= 400 && response.code() < 500 && response.code() != 429;
		}
		catch (IOException e)
		{
			log.debug("Ingest unreachable for {}: {}", event.type, e.getMessage());
			return false;
		}
	}

	private static final class QueuedEvent
	{
		final String type;
		final JsonObject json;
		final byte[] screenshot;
		int attempts;

		QueuedEvent(JsonObject json, byte[] screenshot)
		{
			this.json = json;
			this.type = json.has("type") ? json.get("type").getAsString() : "?";
			this.screenshot = screenshot;
		}
	}
}

package com.triglav.clan.net;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Fetches GET /api/plugin/config/:key on startup, right after linking and then hourly, so a change
 * on the site (e.g. the screenshot threshold) reaches every plugin within the hour without a restart.
 * docs/plugin-brief.md §4 said 6h; an hour is still one tiny request per member.
 */
@Slf4j
@Singleton
public class ConfigClient
{
	private static final long REFRESH_HOURS = 1;

	private final OkHttpClient httpClient;
	private final KeyStore keyStore;
	private final ScheduledExecutorService executor;
	private final AtomicReference<RemoteConfig> current = new AtomicReference<>(RemoteConfig.DEFAULT);

	@Inject
	private ConfigClient(OkHttpClient httpClient, KeyStore keyStore, ScheduledExecutorService executor)
	{
		this.httpClient = httpClient;
		this.keyStore = keyStore;
		this.executor = executor;
		executor.scheduleWithFixedDelay(this::refresh, 0, REFRESH_HOURS, TimeUnit.HOURS);
	}

	public RemoteConfig current()
	{
		return current.get();
	}

	public void refreshNow()
	{
		executor.execute(this::refresh);
	}

	private void refresh()
	{
		final String clanCode = keyStore.ingestKey();
		if (clanCode == null)
		{
			return;
		}

		final HttpUrl url = HttpUrl.parse(ApiClient.siteUrl() + "/api/plugin/config/" + clanCode);
		if (url == null)
		{
			return;
		}

		final Request request = new Request.Builder().url(url).build();
		try (Response response = httpClient.newCall(request).execute())
		{
			if (!response.isSuccessful() || response.body() == null)
			{
				return;
			}

			final JsonObject body = new JsonParser().parse(response.body().string()).getAsJsonObject();
			final int screenshotMinValue = body.has("screenshotMinValue") ? body.get("screenshotMinValue").getAsInt() : RemoteConfig.DEFAULT.screenshotMinValue;
			final int pollSeconds = body.has("pollSeconds") ? body.get("pollSeconds").getAsInt() : RemoteConfig.DEFAULT.pollSeconds;
			current.set(new RemoteConfig(screenshotMinValue, pollSeconds));
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Could not refresh remote config: {}", e.getMessage());
		}
	}
}

package com.triglav.clan.net;

import com.google.gson.JsonObject;
import net.runelite.api.Client;
import net.runelite.api.Player;

/**
 * The envelope every ingest event shares (site: src/lib/dink/schema.ts). Kept identical to
 * what Dink sends so the site's existing parser needs no changes. The site rejects an empty
 * `playerName`, so callers that may run without a loaded local player (logout) pass the name in.
 */
public final class Envelope
{
	private Envelope()
	{
	}

	/** @return the local player's name, or null while the player isn't loaded (login screen, first login ticks) */
	public static String playerName(Client client)
	{
		final Player local = client.getLocalPlayer();
		final String name = local == null ? null : local.getName();
		return name == null || name.isEmpty() ? null : name;
	}

	public static JsonObject create(Client client, String type, JsonObject extra)
	{
		return create(client, type, extra, playerName(client));
	}

	public static JsonObject create(Client client, String type, JsonObject extra, String playerName)
	{
		final JsonObject envelope = new JsonObject();
		envelope.addProperty("type", type);
		envelope.addProperty("playerName", playerName == null ? "" : playerName);
		envelope.addProperty("accountType", client.getAccountType().name());
		envelope.addProperty("dinkAccountHash", Long.toString(client.getAccountHash()));
		envelope.addProperty("world", client.getWorld());
		final Player local = client.getLocalPlayer();
		if (local != null && local.getWorldLocation() != null)
		{
			envelope.addProperty("regionId", local.getWorldLocation().getRegionID());
		}
		envelope.add("extra", extra == null ? new JsonObject() : extra);
		return envelope;
	}
}

package com.triglav.clan.net;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.triglav.clan.TriglavConfig;
import java.io.IOException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Turns the member's permanent clan code (TRG-XXXX from clan.kokalj.dev/profil) into the ingest key
 * every endpoint uses, via POST /api/plugin/link. The last key is cached in the config so the plugin
 * keeps working when the site is unreachable at startup. A value that isn't a TRG code is taken as
 * the raw ingest key itself (the key from the Dink URL still works).
 */
@Slf4j
@Singleton
public class KeyStore
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final String CACHED_KEY = "ingestKey";

	public enum Result
	{
		LINKED, WRONG_CODE, UNREACHABLE, EMPTY
	}

	private final OkHttpClient httpClient;
	private final TriglavConfig config;
	private final ConfigManager configManager;
	private final ScheduledExecutorService executor;

	private volatile String ingestKey;
	private volatile String linkedName;

	@Inject
	private KeyStore(OkHttpClient httpClient, TriglavConfig config, ConfigManager configManager, ScheduledExecutorService executor)
	{
		this.httpClient = httpClient;
		this.config = config;
		this.configManager = configManager;
		this.executor = executor;
		this.ingestKey = configManager.getConfiguration(TriglavConfig.GROUP, CACHED_KEY);
	}

	/** @return the ingest key, or null if not linked */
	public String ingestKey()
	{
		final String key = ingestKey;
		return key == null || key.isEmpty() ? null : key;
	}

	public boolean isLinked()
	{
		return ingestKey() != null;
	}

	/** @return the Discord name the code belongs to, once confirmed by the site this session */
	public String linkedName()
	{
		return linkedName;
	}

	/** Resolves the configured clan code off the client thread and reports the outcome. */
	public void refresh(Consumer<Result> onDone)
	{
		executor.execute(() -> onDone.accept(resolve()));
	}

	private Result resolve()
	{
		final String raw = config.clanCode() == null ? "" : config.clanCode().trim();
		if (raw.isEmpty())
		{
			store(null, null);
			return Result.EMPTY;
		}

		if (!isClanCode(raw))
		{
			store(raw, null);
			return Result.LINKED;
		}

		final HttpUrl url = HttpUrl.parse(ApiClient.siteUrl() + "/api/plugin/link");
		if (url == null)
		{
			return Result.UNREACHABLE;
		}

		final JsonObject body = new JsonObject();
		body.addProperty("code", raw);
		final Request request = new Request.Builder().url(url).post(RequestBody.create(JSON, body.toString())).build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (response.code() == 404)
			{
				store(null, null);
				return Result.WRONG_CODE;
			}
			if (!response.isSuccessful() || response.body() == null)
			{
				return Result.UNREACHABLE;
			}

			final JsonObject json = new JsonParser().parse(response.body().string()).getAsJsonObject();
			store(json.get("ingestKey").getAsString(), json.has("name") ? json.get("name").getAsString() : null);
			return Result.LINKED;
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Could not link clan code: {}", e.getMessage());
			return Result.UNREACHABLE;
		}
	}

	private void store(String key, String name)
	{
		ingestKey = key;
		linkedName = name;
		if (key == null)
		{
			configManager.unsetConfiguration(TriglavConfig.GROUP, CACHED_KEY);
		}
		else
		{
			configManager.setConfiguration(TriglavConfig.GROUP, CACHED_KEY, key);
		}
	}

	/** "TRG-2A3B", "trg 2a3b", "TRG2A3B" */
	static boolean isClanCode(String raw)
	{
		return raw.toUpperCase().replaceAll("[^A-Z0-9]", "").matches("TRG[A-Z0-9]{4}");
	}
}

