/** Parsed GET /api/plugin/overview/:key (site: src/app/api/plugin/overview/[key]/route.ts). */
public final class Overview
{
	public static final Overview EMPTY = new Overview(null, 0, 0, Collections.emptyList(), Collections.emptyList(),
		Collections.emptyList(), Collections.emptyList(), 0L);

	/** Where the group meets: OSRS tile coordinates, plane and an optional place name. */
	public static final class Loc
	{
		public final int x;
		public final int y;
		public final int plane;
		public final String name;

		Loc(int x, int y, int plane, String name)
		{
			this.x = x;
			this.y = y;
			this.plane = plane;
			this.name = name;
		}

		public String label()
		{
			return name == null || name.isEmpty() ? x + ", " + y : name;
		}
	}

	public static final class Event
	{
		public final String id;
		public final String title;
		public final Instant startsAt;
		/** null when the site has no end time for the event */
		public final Instant endsAt;
		public final int going;
		public final boolean mine;
		public final Loc loc;
		/** URL of the icon on the clan site, or null */
		public final String icon;

		Event(String id, String title, Instant startsAt, Instant endsAt, int going, boolean mine, Loc loc, String icon)
		{
			this.loc = loc;
			this.icon = icon;
			this.id = id;
			this.title = title;
			this.startsAt = startsAt;
			this.endsAt = endsAt;
			this.going = going;
			this.mine = mine;
