			this.current = current;
			this.target = target;
		}
	}

	public final String rsn;
	public final int points;
	public final int deathsThisMonth;
	public final long valueLostThisMonth;
	public final List<Event> events;
	public final List<Lfg> lfg;
	public final List<MyLfg> myLfg;
	public final List<Goal> goals;

	private Overview(String rsn, int points, int deathsThisMonth, List<Event> events, List<Lfg> lfg, List<MyLfg> myLfg,
		List<Goal> goals, long valueLostThisMonth)
	{
		this.rsn = rsn;
		this.points = points;
		this.deathsThisMonth = deathsThisMonth;
		this.events = events;
		this.lfg = lfg;
		this.myLfg = myLfg;
		this.goals = goals;
		this.valueLostThisMonth = valueLostThisMonth;
	}

	public static Overview parse(JsonObject body)
	{
		final JsonObject me = obj(body, "me");
		final JsonObject deaths = obj(body, "deaths");

		final List<Event> events = new ArrayList<>();
		for (JsonElement e : array(body, "events"))
		{
			final JsonObject o = e.getAsJsonObject();
			events.add(new Event(str(o, "id"), str(o, "title"), time(o, "startsAt"),
				o.has("endsAt") && !o.get("endsAt").isJsonNull() ? time(o, "endsAt") : null, integer(o, "going"),
				o.has("mine") && !o.get("mine").isJsonNull() && "YES".equals(o.get("mine").getAsString()), loc(o), nullableStr(o, "icon")));
		}

		final List<Lfg> lfg = new ArrayList<>();
		for (JsonElement e : array(body, "lfg"))
		{
			final JsonObject o = e.getAsJsonObject();
			lfg.add(new Lfg(str(o, "id"), str(o, "title"), str(o, "activity"), time(o, "startsAt"),
				integer(o, "capacity"), integer(o, "taken"), o.has("mine") && o.get("mine").getAsBoolean(),
				o.has("owner") && o.get("owner").getAsBoolean(), loc(o), nullableStr(o, "icon")));
		}

		final List<MyLfg> mine = new ArrayList<>();
		for (JsonElement e : array(body, "myLfg"))
		{
			final JsonObject o = e.getAsJsonObject();
			final JsonObject gear = o.has("gear") && o.get("gear").isJsonObject() ? o.getAsJsonObject("gear") : null;
			mine.add(new MyLfg(str(o, "id"), str(o, "title"), str(o, "activity"), time(o, "startsAt"), loc(o), nullableStr(o, "icon"),
				gear == null ? null : str(gear, "title"),
				gear == null ? Collections.emptyList() : gearItems(array(gear, "equipment")),
				gear == null ? Collections.emptyList() : gearItems(array(gear, "inventory"))));
		}

		final List<Goal> goals = new ArrayList<>();
		for (JsonElement e : array(body, "goals"))
		{
			final JsonObject o = e.getAsJsonObject();
			goals.add(new Goal(str(o, "title"), integer(o, "current"), integer(o, "target")));
		}


		return new Overview(me.has("rsn") && !me.get("rsn").isJsonNull() ? me.get("rsn").getAsString() : null,
			integer(me, "points"), integer(deaths, "month"), events, lfg, mine, goals, longValue(deaths, "valueLost"));
	}

	private static String nullableStr(JsonObject o, String key)
	{
		return o.has(key) && !o.get(key).isJsonNull() ? o.get(key).getAsString() : null;
	}

	private static Loc loc(JsonObject o)
	{
		if (!o.has("loc") || !o.get("loc").isJsonObject())
		{
			return null;
		}

		final JsonObject l = o.getAsJsonObject("loc");
		return new Loc(integer(l, "x"), integer(l, "y"), integer(l, "plane"), l.has("name") && !l.get("name").isJsonNull() ? l.get("name").getAsString() : null);
	}

	private static List<GearItem> gearItems(JsonArray items)
	{
		final List<GearItem> out = new ArrayList<>();
		for (JsonElement e : items)
		{
			final JsonObject o = e.getAsJsonObject();
			out.add(new GearItem(integer(o, "id"), str(o, "name"), o.has("qty") ? Math.max(1, integer(o, "qty")) : 1));
		}
		return out;
	}

	private static JsonObject obj(JsonObject parent, String key)
	{
		return parent.has(key) && parent.get(key).isJsonObject() ? parent.getAsJsonObject(key) : new JsonObject();
	}

	private static JsonArray array(JsonObject parent, String key)
	{
		return parent.has(key) && parent.get(key).isJsonArray() ? parent.getAsJsonArray(key) : new JsonArray();
	}

	private static String str(JsonObject o, String key)
	{
		return o.has(key) && !o.get(key).isJsonNull() ? o.get(key).getAsString() : "";
	}

	private static int integer(JsonObject o, String key)
	{
		return o.has(key) && !o.get(key).isJsonNull() ? o.get(key).getAsInt() : 0;
	}

	private static long longValue(JsonObject o, String key)
	{
		return o.has(key) && !o.get(key).isJsonNull() ? o.get(key).getAsLong() : 0L;
	}

	private static Instant time(JsonObject o, String key)
	{
		try
		{
			return Instant.parse(str(o, key));
		}
		catch (RuntimeException e)
		{
			return Instant.EPOCH;
		}
	}
}

package com.triglav.clan.overview;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.triglav.clan.net.ApiClient;
import com.triglav.clan.net.KeyStore;
import java.io.IOException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Polls GET /api/plugin/overview/:key once a minute: events, LFG, clan goals, deaths and points
 * in one request instead of one per panel section. The latest snapshot is kept, and a listener
 * is told whenever a fresh one lands.
 */
@Slf4j
@Singleton
public class OverviewClient
{
	private static final int POLL_SECONDS = 60;
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	private final OkHttpClient httpClient;
	private final KeyStore keyStore;
	private final ScheduledExecutorService executor;
	private final AtomicReference<Overview> current = new AtomicReference<>(Overview.EMPTY);
	/** The character being played: LFG state and joins are per RSN, one Discord user can have several accounts. */
	private volatile String rsn;
	private volatile Consumer<Overview> listener = overview ->
	{
	};

	@Inject
	private OverviewClient(OkHttpClient httpClient, KeyStore keyStore, ScheduledExecutorService executor)
	{
		this.httpClient = httpClient;
		this.keyStore = keyStore;
		this.executor = executor;
		executor.scheduleWithFixedDelay(this::refresh, 3, POLL_SECONDS, TimeUnit.SECONDS);
	}

	public Overview current()
	{
		return current.get();
	}

	public void setListener(Consumer<Overview> listener)
	{
		this.listener = listener;
	}

	public void setRsn(String rsn)
	{
		this.rsn = rsn;
	}

	public void refreshNow()
	{
		executor.execute(this::refresh);
	}

	private void refresh()
	{
		final String key = keyStore.ingestKey();
		if (key == null)
		{
			current.set(Overview.EMPTY);
			return;
		}

		final HttpUrl base = HttpUrl.parse(ApiClient.siteUrl() + "/api/plugin/overview/" + key);
		if (base == null)
		{
			return;
		}

		final HttpUrl url = rsn == null ? base : base.newBuilder().addQueryParameter("rsn", rsn).build();

		try (Response response = httpClient.newCall(new Request.Builder().url(url).build()).execute())
		{
			if (!response.isSuccessful() || response.body() == null)
			{
				return;
			}

			final Overview overview = Overview.parse(new JsonParser().parse(response.body().string()).getAsJsonObject());
			current.set(overview);
			listener.accept(overview);
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Overview poll failed: {}", e.getMessage());
		}
	}

	/** Join (or, with leave=true, leave) an LFG; @param onResult human-readable result for the game chat */
	public void joinLfg(String postId, boolean leave, Consumer<String> onResult)
	{
		final String key = keyStore.ingestKey();
		if (key == null)
		{
			onResult.accept("najprej poveži račun.");
			return;
		}

		executor.execute(() ->
		{
			final HttpUrl url = HttpUrl.parse(ApiClient.siteUrl() + "/api/plugin/lfg/" + key + "/join");
			if (url == null)
			{
				return;
			}

			final JsonObject body = new JsonObject();
			body.addProperty("postId", postId);
			body.addProperty("leave", leave);
			if (rsn != null)
			{
				body.addProperty("rsn", rsn);
			}
			final Request request = new Request.Builder().url(url).post(RequestBody.create(JSON, body.toString())).build();

			try (Response response = httpClient.newCall(request).execute())
			{
				final String raw = response.body() == null ? "" : response.body().string();
				final JsonObject json = raw.isEmpty() ? new JsonObject() : new JsonParser().parse(raw).getAsJsonObject();
				if (response.isSuccessful())
				{
					onResult.accept(json.has("message") ? json.get("message").getAsString() : "ok.");
					refresh();
				}
				else
				{
					onResult.accept(json.has("error") ? json.get("error").getAsString() : "ni uspelo (HTTP " + response.code() + ").");
				}
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("LFG join failed", e);
				onResult.accept("ni uspelo — stran ni dosegljiva.");
			}
		});
	}
}

package com.triglav.clan.remind;

import com.triglav.clan.overview.Overview;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntUnaryOperator;

/**
 * Compares what the member is carrying with the setup an LFG recommends. Equipment and inventory
 * are checked together: a setup that wants a whip equipped is satisfied by a whip in the inventory
 * too, since the point is "did I bring it", not "is it on". Item ids are canonicalised on both
 * sides so noted/placeholder variants match.
 */
public final class GearCheck
{
	private GearCheck()
	{
	}

	/** @param have canonical item id -> total quantity across inventory and worn equipment */
	public static List<String> missing(Overview.MyLfg lfg, Map<Integer, Integer> have, IntUnaryOperator canonical)
	{
		final Map<Integer, Integer> needed = new LinkedHashMap<>();
		final Map<Integer, String> names = new LinkedHashMap<>();
		for (Overview.GearItem item : lfg.equipment)
		{
			need(needed, names, canonical.applyAsInt(item.id), item.name, 1);
		}
		for (Overview.GearItem item : lfg.inventory)
		{
			need(needed, names, canonical.applyAsInt(item.id), item.name, item.quantity);
		}

		final List<String> out = new ArrayList<>();
		for (Map.Entry<Integer, Integer> entry : needed.entrySet())
		{
			final int missing = entry.getValue() - have.getOrDefault(entry.getKey(), 0);
			if (missing > 0)
			{
				out.add(missing > 1 ? names.get(entry.getKey()) + " x" + missing : names.get(entry.getKey()));
			}
		}
		return out;
	}

	private static void need(Map<Integer, Integer> needed, Map<Integer, String> names, int id, String name, int quantity)
	{
		needed.merge(id, quantity, Integer::sum);
		names.putIfAbsent(id, name);
	}
}

package com.triglav.clan.remind;

import com.triglav.clan.net.ApiClient;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.ImageUtil;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Icons for the countdown box (a boss, a skill, an event type). The site resizes and caches them
 * (src/app/api/icon), so the plugin only ever talks to the clan site. Fetched once per URL off the
 * game thread; until an icon arrives (or if it never does) the caller keeps using its fallback.
 */
@Slf4j
@Singleton
public class IconCache
{
	private static final int SIZE = 32;

	private final OkHttpClient httpClient;
	private final ScheduledExecutorService executor;
	private final Map<String, BufferedImage> images = new ConcurrentHashMap<>();
	private final Set<String> requested = ConcurrentHashMap.newKeySet();

	@Inject
	private IconCache(OkHttpClient httpClient, ScheduledExecutorService executor)
	{
		this.httpClient = httpClient;
		this.executor = executor;
	}

	/** @return the icon if it has already been fetched, otherwise null (and a fetch is started) */
	public BufferedImage get(String url)
	{
		if (url == null || url.isEmpty())
		{
			return null;
		}

		final BufferedImage cached = images.get(url);
		if (cached == null && requested.add(url))
		{
			executor.execute(() -> fetch(url));
		}
		return cached;
	}

	private void fetch(String url)
	{
		// Only the clan site: the plugin never fetches from anywhere else.
		final HttpUrl parsed = HttpUrl.parse(url);
		final HttpUrl site = HttpUrl.parse(ApiClient.siteUrl());
		if (parsed == null || site == null || !parsed.host().equals(site.host()))
		{
			return;
		}

		try (Response response = httpClient.newCall(new Request.Builder().url(parsed).build()).execute())
		{
			if (!response.isSuccessful() || response.body() == null)
			{
				requested.remove(url); // try again later
				return;
			}

			try (InputStream in = response.body().byteStream())
			{
				final BufferedImage image = ImageIO.read(in);
				if (image != null)
				{
					images.put(url, ImageUtil.resizeImage(image, SIZE, SIZE, true));
				}
			}
		}
		catch (IOException | RuntimeException e)
		{
			requested.remove(url);
			log.debug("Icon fetch failed for {}: {}", url, e.getMessage());
		}
	}
}

package com.triglav.clan.remind;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.time.Duration;
import java.time.Instant;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;

/** Small countdown next to the minimap while an LFG the member joined is about to start. */
final class LfgInfoBox extends InfoBox
{
	private volatile Instant startsAt = Instant.EPOCH;
	private volatile Instant endsAt;
	private volatile String title = "";
	private volatile String kind = "LFG";
	private volatile String place = "";

	LfgInfoBox(BufferedImage image, Plugin plugin)
	{
		super(image, plugin);
	}

	/** @param endsAt when the thing ends, or null; while it runs the box counts down to this instead */
	void update(String kind, String title, Instant startsAt, Instant endsAt, String place)
	{
		this.place = place == null ? "" : place;
		this.kind = kind;
		this.title = title;
		this.startsAt = startsAt;
		this.endsAt = endsAt;
	}

	private boolean running()
	{
		return endsAt != null && !Instant.now().isBefore(startsAt);
	}

	@Override
	public String getText()
	{
		if (running())
		{
			final long left = Duration.between(Instant.now(), endsAt).toMinutes();
			return left >= 60 ? (left / 60) + "h" : Math.max(0, left) + "m";
		}

		final long minutes = Duration.between(Instant.now(), startsAt).toMinutes();
		return minutes <= 0 ? "zdaj" : minutes + "m";
	}

	@Override
	public Color getTextColor()
	{
		if (running())
		{
			return Color.GREEN;
		}
		return Duration.between(Instant.now(), startsAt).toMinutes() <= 5 ? Color.ORANGE : Color.WHITE;
	}

	@Override
	public String getTooltip()
	{
		return kind + ": " + title + (running() ? " (v teku)" : "") + (place.isEmpty() ? "" : " · " + place);
	}
}

package com.triglav.clan.remind;

import com.triglav.clan.TriglavConfig;
import com.triglav.clan.overview.Overview;
import com.triglav.clan.overview.OverviewClient;
import java.awt.image.BufferedImage;
import java.time.Duration;
import java.time.Instant;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;
import net.runelite.client.util.ImageUtil;

/**
 * An LFG the member joined: a chat reminder ten minutes before, the setup check against the post's
 * recommended gear, and a countdown next to the minimap from half an hour out. Everything is driven
 * by the game tick (one cheap clock comparison per tick) off the overview snapshot, so no extra
 * request is made. Each LFG is reminded once per session.
 */
@Singleton
public class LfgReminder
{
	private static final long REMIND_MINUTES = 10;
	private static final long INFOBOX_MINUTES = 30;
	private static final long LINGER_MINUTES = 5;
	private static final int MAX_LISTED = 5;

	private final Client client;
	private final ItemManager itemManager;
	private final InfoBoxManager infoBoxManager;
	private final OverviewClient overviewClient;
	private final TriglavConfig config;
	private final Set<String> reminded = new HashSet<>();
	private final LocationMarker marker;
	private final BufferedImage pluginIcon;
	private final IconCache iconCache;

	private LfgInfoBox infoBox;
	private BufferedImage infoBoxImage;

	@Inject
	private LfgReminder(Client client, ItemManager itemManager, InfoBoxManager infoBoxManager, OverviewClient overviewClient, TriglavConfig config,
		LocationMarker marker, IconCache iconCache)
	{
		this.marker = marker;
		this.iconCache = iconCache;
		this.pluginIcon = ImageUtil.resizeImage(ImageUtil.loadImageResource(LfgReminder.class, "/icon.png"), 32, 32);
		this.client = client;
		this.itemManager = itemManager;
		this.infoBoxManager = infoBoxManager;
		this.overviewClient = overviewClient;
		this.config = config;
	}

	/** Game thread. */
	public void onGameTick(Plugin plugin, Consumer<String> chat)
	{
		if (!config.lfgReminders())
		{
			removeInfoBox();
			return;
		}

		final Instant now = Instant.now();
		String nextKind = null;
		String nextTitle = null;
		Instant nextStart = null;
		Instant nextEnd = null;
		Overview.Loc nextLoc = null;
		String nextIcon = null;

		for (Overview.MyLfg lfg : overviewClient.current().myLfg)
		{
			final long minutes = Duration.between(now, lfg.startsAt).toMinutes();
			if (minutes < -LINGER_MINUTES)
			{
				continue;
			}

			if (nextStart == null || lfg.startsAt.isBefore(nextStart))
			{
				nextKind = "LFG";
				nextTitle = lfg.title;
				nextStart = lfg.startsAt;
				nextEnd = null;
				nextLoc = lfg.loc;
				nextIcon = lfg.icon;
			}

			if (minutes <= REMIND_MINUTES && reminded.add("lfg:" + lfg.id))
			{
				chat.accept(minutes <= 0 ? "LFG »" + lfg.title + "« se zacenja zdaj." : "LFG »" + lfg.title + "« se zacne cez " + Math.max(1, minutes) + " min.");
				if (lfg.loc != null)
				{
					chat.accept("lokacija: " + lfg.loc.label() + " (" + lfg.loc.x + ", " + lfg.loc.y + ") - oznaceno na zemljevidu.");
				}
				if (lfg.hasGear())
				{
					checkGear(lfg, chat);
				}
			}
		}

		// Clan events: ones the member is going to get the reminder; every running event (a BOTW or SOTW that
		// is on right now) shows in the box, since a competition is clan-wide whether or not you signed up.
		for (Overview.Event event : overviewClient.current().events)
		{
			final long minutes = Duration.between(now, event.startsAt).toMinutes();
			final boolean running = minutes <= 0 && (event.endsAt == null ? minutes >= -LINGER_MINUTES : now.isBefore(event.endsAt));
			if (!running && minutes < 0)
			{
				continue;
			}

			if (event.mine && minutes <= REMIND_MINUTES && reminded.add("event:" + event.id))
			{
				chat.accept(minutes <= 0 ? "Dogodek »" + event.title + "« se zacenja zdaj." : "Dogodek »" + event.title + "« se zacne cez " + Math.max(1, minutes) + " min.");
				if (event.loc != null)
				{
					chat.accept("lokacija: " + event.loc.label() + " (" + event.loc.x + ", " + event.loc.y + ") - oznaceno na zemljevidu.");
				}
			}

			final boolean show = running || (event.mine && minutes <= INFOBOX_MINUTES);
			if (show && (nextStart == null || running || event.startsAt.isBefore(nextStart)))
			{
				nextKind = "Dogodek";
				nextTitle = event.title;
				nextStart = event.startsAt;
				nextEnd = event.endsAt;
				nextLoc = event.loc;
				nextIcon = event.icon;
			}
		}

		final boolean showBox = nextStart != null
			&& (nextEnd != null && !now.isBefore(nextStart) || Duration.between(now, nextStart).toMinutes() <= INFOBOX_MINUTES);
		if (showBox)
		{
			showInfoBox(plugin, nextKind, nextTitle, nextStart, nextEnd, nextLoc, nextIcon);
			marker.show(nextLoc, nextTitle);
		}
		else
		{
			removeInfoBox();
		}
	}

	/** The soonest joined LFG that has a recommended setup, or null. */
	public Overview.MyLfg nextWithGear()
	{
		final Instant now = Instant.now();
		Overview.MyLfg best = null;
		for (Overview.MyLfg lfg : overviewClient.current().myLfg)
		{
			if (lfg.hasGear() && Duration.between(now, lfg.startsAt).toMinutes() >= -LINGER_MINUTES
				&& (best == null || lfg.startsAt.isBefore(best.startsAt)))
			{
				best = lfg;
			}
		}
		return best;
	}

	/** Game thread: reads inventory and worn equipment. */
	public void checkGear(Overview.MyLfg lfg, Consumer<String> chat)
	{
		final Map<Integer, Integer> have = new HashMap<>();
		count(have, client.getItemContainer(InventoryID.INVENTORY));
		count(have, client.getItemContainer(InventoryID.EQUIPMENT));

		final List<String> missing = GearCheck.missing(lfg, have, itemManager::canonicalize);
		if (missing.isEmpty())
		{
			chat.accept("oprema za »" + lfg.title + "« (" + lfg.gearTitle + ") je v redu.");
			return;
		}

		final List<String> shown = missing.size() > MAX_LISTED ? missing.subList(0, MAX_LISTED) : missing;
		chat.accept("za »" + lfg.title + "« manjka: " + String.join(", ", shown)
			+ (missing.size() > MAX_LISTED ? " in se " + (missing.size() - MAX_LISTED) + " drugega" : "") + ".");
	}

	public void shutDown()
	{
		removeInfoBox();
		reminded.clear();
	}

	private void count(Map<Integer, Integer> have, ItemContainer container)
	{
		if (container == null)
		{
			return;
		}

		for (Item item : container.getItems())
		{
			if (item.getId() > 0)
			{
				have.merge(itemManager.canonicalize(item.getId()), item.getQuantity(), Integer::sum);
			}
		}
	}

	private void showInfoBox(Plugin plugin, String kind, String title, Instant startsAt, Instant endsAt, Overview.Loc loc, String iconUrl)
	{
		// The boss, skill or event-type icon from the site once it has arrived; the plugin icon until then.
		final BufferedImage wanted = iconCache.get(iconUrl) != null ? iconCache.get(iconUrl) : pluginIcon;
		if (infoBox == null)
		{
			infoBox = new LfgInfoBox(wanted, plugin);
			infoBoxImage = wanted;
			infoBoxManager.addInfoBox(infoBox);
		}
		else if (infoBoxImage != wanted)
		{
			infoBox.setImage(wanted);
			infoBoxImage = wanted;
		}
		infoBox.update(kind, title, startsAt, endsAt, loc == null ? null : loc.label());
	}

	private void removeInfoBox()
	{
		marker.clear();
		if (infoBox != null)
		{
			infoBoxManager.removeInfoBox(infoBox);
			infoBox = null;
		}
	}
}

package com.triglav.clan.remind;

import com.triglav.clan.overview.Overview;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;

/**
 * Where the group meets, shown on the world map (always, with the place name on hover and a click
 * that jumps the map to it) and as a pin on the minimap while the spot is in view
 * (see {@link LocationOverlay}). One marker at a time: the one for the box that is showing.
 */
@Singleton
public class LocationMarker
{
	static final Color GOLD = new Color(0xd8a93f);

	private final WorldMapPointManager worldMapPointManager;
	private final BufferedImage pin = pinImage();

	private WorldMapPoint point;
	private volatile WorldPoint target;
	private Overview.Loc shown;
	private String shownLabel;

	@Inject
	private LocationMarker(WorldMapPointManager worldMapPointManager)
	{
		this.worldMapPointManager = worldMapPointManager;
	}

	/** @return where the minimap pin goes, or null when there is nothing to show */
	WorldPoint target()
	{
		return target;
	}

	/** Game thread. Re-sets only when the location actually changed. */
	void show(Overview.Loc loc, String label)
	{
		if (loc == null)
		{
			clear();
			return;
		}

		if (shown != null && shown.x == loc.x && shown.y == loc.y && shown.plane == loc.plane && label.equals(shownLabel))
		{
			return;
		}

		clear();
		shown = loc;
		shownLabel = label;
		target = new WorldPoint(loc.x, loc.y, loc.plane);
		point = WorldMapPoint.builder()
			.worldPoint(target)
			.image(pin)
			.tooltip(label + " · " + loc.label())
			.snapToEdge(true)
			.jumpOnClick(true)
			.build();
		worldMapPointManager.add(point);
	}

	void clear()
	{
		if (point != null)
		{
			worldMapPointManager.remove(point);
			point = null;
		}
		target = null;
		shown = null;
		shownLabel = null;
	}

	private static BufferedImage pinImage()
	{
		final BufferedImage image = new BufferedImage(18, 18, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(Color.BLACK);
		g.fillOval(1, 1, 16, 16);
		g.setColor(GOLD);
		g.fillOval(3, 3, 12, 12);
		g.setColor(Color.BLACK);
		g.fillOval(7, 7, 4, 4);
		g.dispose();
		return image;
	}
}

package com.triglav.clan.remind;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** A gold pin on the minimap at the meeting spot, whenever that spot is inside the loaded area. */
@Singleton
public class LocationOverlay extends Overlay
{
	private static final int RADIUS = 5;

	private final Client client;
	private final LocationMarker marker;

	@Inject
	private LocationOverlay(Client client, LocationMarker marker)
	{
		this.client = client;
		this.marker = marker;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		final WorldPoint target = marker.target();
		if (target == null || client.getLocalPlayer() == null || target.getPlane() != client.getPlane())
		{
			return null;
		}

		final LocalPoint local = LocalPoint.fromWorld(client, target);
		if (local == null)
		{
			return null; // outside the loaded scene: the world map marker still shows it
		}

		final Point minimap = Perspective.localToMinimap(client, local);
		if (minimap == null)
		{
			return null;
		}

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(Color.BLACK);
		g.fillOval(minimap.getX() - RADIUS - 1, minimap.getY() - RADIUS - 1, RADIUS * 2 + 2, RADIUS * 2 + 2);
		g.setColor(LocationMarker.GOLD);
		g.fillOval(minimap.getX() - RADIUS, minimap.getY() - RADIUS, RADIUS * 2, RADIUS * 2);
		return null;
	}
}

package com.triglav.clan.share;

import com.google.gson.JsonObject;
import com.triglav.clan.TriglavConfig;
import com.triglav.clan.net.ApiClient;
import com.triglav.clan.net.Envelope;
import com.triglav.clan.net.KeyStore;
import java.io.IOException;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.WorldType;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarbitID;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Live location for the clan map (site: /zemljevid/zivo), strictly opt-in: nothing is sent unless the
 * member ticks "Deli mojo lokacijo" in the plugin settings. One position every ~30 s, no trail. It is
 * never sent where being findable is dangerous - the wilderness, PvP / Deadman / Last Man Standing worlds
 * and instanced areas (raids, where coordinates are meaningless anyway) - and the site is told to forget
 * it the moment sharing stops, the member logs out or enters such an area.
 */
@Slf4j
@Singleton
public class LocationSharer
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final int INTERVAL_TICKS = 50; // ~30 s

	private final Client client;
	private final TriglavConfig config;
	private final KeyStore keyStore;
	private final OkHttpClient httpClient;
	private final ScheduledExecutorService executor;

	private int ticks;
	private boolean sentSomething;
	/** RSN of the last position sent, so clearing withdraws that character only. */
	private volatile String sentRsn;

	@Inject
	private LocationSharer(Client client, TriglavConfig config, KeyStore keyStore, OkHttpClient httpClient, ScheduledExecutorService executor)
	{
		this.client = client;
		this.config = config;
		this.keyStore = keyStore;
		this.httpClient = httpClient;
		this.executor = executor;
	}

	/** Game thread, every tick. */
	public void onGameTick()
	{
		if (!config.shareLocation() || !keyStore.isLinked() || client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
		{
			clear();
			return;
		}

		if (isSensitive(client, config.shareLocationDanger()))
		{
			clear();
			return;
		}

		if (++ticks < INTERVAL_TICKS && sentSomething)
		{
			return;
		}
		ticks = 0;

		final WorldPoint here = client.getLocalPlayer().getWorldLocation();
		final JsonObject body = new JsonObject();
		body.addProperty("x", here.getX());
		body.addProperty("y", here.getY());
		body.addProperty("plane", here.getPlane());
		body.addProperty("world", client.getWorld());
		// the character being played: one Discord user can have several accounts, each shows on the map
		final String name = Envelope.playerName(client);
		if (name != null)
		{
			body.addProperty("rsn", name);
		}
		sentRsn = name;
		sentSomething = true;
		post(body);
	}

	/** Forget the last position on the site; a no-op if nothing was sent. Safe from any thread. */
	public void clear()
	{
		ticks = 0;
		if (!sentSomething)
		{
			return;
		}

		sentSomething = false;
		final JsonObject body = new JsonObject();
		body.addProperty("clear", true);
		if (sentRsn != null)
		{
			body.addProperty("rsn", sentRsn);
		}
		post(body);
	}

	/**
	 * Instances are never shared. The wilderness and PvP-type worlds are not shared either, unless the member
	 * ticked the extra "also in the wilderness and on PvP/Deadman" setting; anything already sent is withdrawn.
	 */
	static boolean isSensitive(Client client, boolean allowDanger)
	{
		if (client.isInInstancedRegion())
		{
			return true;
		}

		return !allowDanger && isDangerous(client);
	}

	private static boolean isDangerous(Client client)
	{
		final Set<WorldType> world = client.getWorldType();
		return client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) == 1
			|| world.contains(WorldType.PVP)
			|| world.contains(WorldType.BOUNTY)
			|| world.contains(WorldType.HIGH_RISK)
			|| world.contains(WorldType.DEADMAN)
			|| world.contains(WorldType.LAST_MAN_STANDING)
			|| world.contains(WorldType.PVP_ARENA)
			|| world.contains(WorldType.TOURNAMENT_WORLD);
	}

	private void post(JsonObject body)
	{
		final String key = keyStore.ingestKey();
		if (key == null)
		{
			return;
		}

		executor.execute(() ->
		{
			final HttpUrl url = HttpUrl.parse(ApiClient.siteUrl() + "/api/plugin/location/" + key);
			if (url == null)
			{
				return;
			}

			try (Response response = httpClient.newCall(new Request.Builder().url(url).post(RequestBody.create(JSON, body.toString())).build()).execute())
			{
				if (!response.isSuccessful())
				{
					log.debug("Location share rejected: HTTP {}", response.code());
				}
			}
			catch (IOException | RuntimeException e)
			{
				log.debug("Location share failed: {}", e.getMessage());
			}
		});
	}
}

package com.triglav.clan.share;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.triglav.clan.net.ApiClient;
import com.triglav.clan.net.KeyStore;
import java.io.IOException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/** "Povej klanu": a screenshot and a short line to POST /api/plugin/share/:key, which posts them to Discord. */
@Slf4j
@Singleton
public class ShareClient
{
	private static final MediaType PNG = MediaType.parse("image/png");
	public static final int MAX_TEXT = 200;

	private final OkHttpClient httpClient;
	private final KeyStore keyStore;
	private final ScheduledExecutorService executor;

	@Inject
	private ShareClient(OkHttpClient httpClient, KeyStore keyStore, ScheduledExecutorService executor)
	{
		this.httpClient = httpClient;
		this.keyStore = keyStore;
		this.executor = executor;
	}

	/** @param png screenshot bytes, or null to share the text alone */
	public void share(String text, byte[] png, Consumer<String> onResult)
	{
		final String key = keyStore.ingestKey();
		if (key == null)
		{
			onResult.accept("najprej poveži račun.");
			return;
		}

		executor.execute(() ->
		{
			final HttpUrl url = HttpUrl.parse(ApiClient.siteUrl() + "/api/plugin/share/" + key);
			if (url == null)
			{
				return;
			}

			final MultipartBody.Builder form = new MultipartBody.Builder().setType(MultipartBody.FORM)
				.addFormDataPart("text", text.length() > MAX_TEXT ? text.substring(0, MAX_TEXT) : text);
			if (png != null)
			{
				form.addFormDataPart("file", "screenshot.png", RequestBody.create(PNG, png));
			}

			try (Response response = httpClient.newCall(new Request.Builder().url(url).post(form.build()).build()).execute())
			{
				if (response.isSuccessful())
				{
					onResult.accept("poslano klanu.");
					return;
				}

				final String raw = response.body() == null ? "" : response.body().string();
				final JsonObject json = raw.isEmpty() ? new JsonObject() : new JsonParser().parse(raw).getAsJsonObject();
				onResult.accept(json.has("error") ? json.get("error").getAsString() : "ni bilo mogoče poslati (HTTP " + response.code() + ").");
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Share failed", e);
				onResult.accept("ni bilo mogoče poslati — stran ni dosegljiva.");
			}
		});
	}
}

package com.triglav.clan.util;

import java.text.Normalizer;

/**
 * The game's own fonts (chat box, overlays) have no č/š/ž — they render as wrong glyphs. Text shown
 * inside the game is therefore folded to plain ASCII ("Čez 15 min" -> "Cez 15 min"). The side panel
 * uses RuneLite's Swing font and keeps the real letters.
 */
public final class GameText
{
	private GameText()
	{
	}

	public static String ascii(String text)
	{
		if (text == null)
		{
			return "";
		}

		final String folded = Normalizer.normalize(text, Normalizer.Form.NFD)
			.replaceAll("\\p{M}", "")
			.replace('—', '-')
			.replace('–', '-')
			.replace('»', '"')
			.replace('«', '"')
			.replace('„', '"')
			.replace('“', '"')
			.replace('”', '"')
			.replace('’', '\'');

		final StringBuilder out = new StringBuilder(folded.length());
		for (char c : folded.toCharArray())
		{
			if (c >= 32 && c < 127)
			{
				out.append(c);
			}
		}
		return out.toString();
	}
}

