package com.triglav.clan.bingo;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.awt.Color;
import org.junit.Test;

public class BingoClientTest
{
	private static JsonObject json(String s)
	{
		return new JsonParser().parse(s).getAsJsonObject();
	}

	@Test
	public void noActiveBingo()
	{
		assertNull(BingoClient.parse(json("{\"bingo\":null}")));
		assertNull(BingoClient.parse(json("{}")));
	}

	@Test
	public void parsesBoard()
	{
		final BingoBoard board = BingoClient.parse(json("{"
			+ "\"bingo\":{\"id\":\"b1\",\"title\":\"Jesenski bingo\",\"rows\":2,\"cols\":2,\"endsAt\":null},"
			+ "\"team\":{\"name\":\"Ekipa 1\",\"color\":\"#3366ff\"},"
			+ "\"tiles\":["
			+ "{\"index\":0,\"title\":\"Bandos page\",\"points\":1,\"iconItemId\":11832,\"itemIds\":[11832,11834],\"status\":\"done\"},"
			+ "{\"index\":1,\"title\":\"Pet\",\"points\":3,\"iconItemId\":null,\"itemIds\":[],\"status\":\"pending\"},"
			+ "{\"index\":2,\"title\":\"Dragon warhammer\",\"points\":2,\"iconItemId\":13576,\"itemIds\":[13576],\"status\":\"open\"}"
			+ "]}"));

		assertEquals("Jesenski bingo", board.title);
		assertEquals(2, board.rows);
		assertEquals(2, board.cols);
		assertEquals("Ekipa 1", board.teamName);
		assertEquals(new Color(0x3366ff), board.teamColor);
		assertEquals(3, board.tiles.size());
		assertEquals(BingoBoard.Status.DONE, board.tiles.get(0).status);
		assertEquals(BingoBoard.Status.PENDING, board.tiles.get(1).status);
		assertEquals(-1, board.tiles.get(1).iconItemId);
		assertEquals(BingoBoard.Status.OPEN, board.tiles.get(2).status);
		assertEquals(3, board.tiles.get(1).points);
		assertEquals(11832, board.tiles.get(0).displayItemId());
		assertEquals(-1, board.tiles.get(1).displayItemId());
	}

	@Test
	public void initialsForTilesWithoutItems()
	{
		assertEquals("BP", BingoOverlay.initials("Boss pet"));
		assertEquals("HC", BingoOverlay.initials("Hard clue unique"));
		assertEquals("PE", BingoOverlay.initials("Pet"));
	}

	@Test
	public void openTileMatchIgnoresFinishedTiles()
	{
		final BingoBoard board = BingoClient.parse(json("{"
			+ "\"bingo\":{\"title\":\"B\",\"rows\":1,\"cols\":2},"
			+ "\"tiles\":["
			+ "{\"index\":0,\"title\":\"a\",\"itemIds\":[11832],\"status\":\"done\"},"
			+ "{\"index\":1,\"title\":\"b\",\"itemIds\":[13576],\"status\":\"open\"}"
			+ "]}"));

		assertFalse(board.hasOpenTileFor(11832));
		assertTrue(board.hasOpenTileFor(13576));
		assertFalse(board.hasOpenTileFor(4151));
	}
}

package com.triglav.clan.collect;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import com.google.gson.JsonObject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import org.junit.Test;

public class ChatParsersTest
{
	private static ChatMessage message(String text)
	{
		return new ChatMessage(null, ChatMessageType.GAMEMESSAGE, "", text, "", 0);
	}

	@Test
	public void readsCompletedClues()
	{
		final JsonObject clue = ClueChat.parse(message("You have completed 1,234 Master Treasure Trails."));
		assertNotNull(clue);
		assertEquals("Master", clue.get("clueType").getAsString());
		assertEquals(1234, clue.get("numberCompleted").getAsInt());

		assertEquals(1, ClueChat.parse(message("You have completed 1 Beginner Treasure Trail.")).get("numberCompleted").getAsInt());
		assertNull(ClueChat.parse(message("You have completed your task! You killed 134 Hellhounds.")));
	}

	@Test
	public void slayerNeedsBothMessages()
	{
		final SlayerChat slayer = new SlayerChat();
		assertNull(slayer.parse(message("You have completed your task! You killed 134 Hellhounds.")));

		final JsonObject done = slayer.parse(message(
			"You've completed 342 tasks and received 15 points, giving you a total of 1,234; return to a Slayer master."));
		assertNotNull(done);
		assertEquals("134 Hellhounds", done.get("slayerTask").getAsString());
		assertEquals("342", done.get("slayerCompleted").getAsString());
		assertEquals("15", done.get("slayerPoints").getAsString());

		// The task name is consumed, so the next completion doesn't reuse it.
		final JsonObject next = slayer.parse(message("You've completed 343 tasks and received 15 points, giving you a total of 1,249."));
		assertNotNull(next);
		assertNull(next.get("slayerTask"));
	}

	@Test
	public void killCountWaitsForTheGameTick()
	{
		final KillCountTracker tracker = new KillCountTracker();
		assertNull(tracker.onGameTick());

		tracker.onChatMessage(message("Your Zulrah kill count is: 1,021."));
		final JsonObject kill = tracker.onGameTick();
		assertNotNull(kill);
		assertEquals("Zulrah", kill.get("boss").getAsString());
		assertEquals(1021, kill.get("count").getAsInt());
		assertNull(kill.get("time"));
		assertEquals(1021, tracker.lastCount("zulrah"));

		// Nothing is left over for the next kill.
		assertNull(tracker.onGameTick());
	}

	@Test
	public void killCountCarriesDurationAndPersonalBest()
	{
		final KillCountTracker tracker = new KillCountTracker();
		tracker.onChatMessage(message("Fight duration: <col=ff0000>1:34.20</col>. Personal best: 1:20.40"));
		tracker.onChatMessage(message("Your Vorkath kill count is: 300."));

		final JsonObject kill = tracker.onGameTick();
		assertNotNull(kill);
		assertEquals("PT1M34.2S", kill.get("time").getAsString());
		assertEquals("PT1M20.4S", kill.get("personalBest").getAsString());
		assertEquals(false, kill.get("isPersonalBest").getAsBoolean());
	}

	@Test
	public void killCountMarksANewPersonalBest()
	{
		final KillCountTracker tracker = new KillCountTracker();
		tracker.onChatMessage(message("Fight duration: <col=ff0000>1:02:03</col> (new personal best)."));
		tracker.onChatMessage(message("Your Chambers of Xeric completion count is: 42."));

		final JsonObject kill = tracker.onGameTick();
		assertNotNull(kill);
		assertEquals("Chambers of Xeric", kill.get("boss").getAsString());
		assertEquals("PT1H2M3S", kill.get("time").getAsString());
		assertEquals("PT1H2M3S", kill.get("personalBest").getAsString());
		assertEquals(true, kill.get("isPersonalBest").getAsBoolean());
	}

	@Test
	public void killCountForgetsADurationWithNoBoss()
	{
		final KillCountTracker tracker = new KillCountTracker();
		tracker.onChatMessage(message("Fight duration: 1:34.20. Personal best: 1:20.40"));
		for (int tick = 0; tick < 11; tick++)
		{
			assertNull(tracker.onGameTick());
		}

		tracker.onChatMessage(message("Your Zulrah kill count is: 5."));
		final JsonObject kill = tracker.onGameTick();
		assertNotNull(kill);
		assertNull(kill.get("time"));
	}
}

package com.triglav.clan.collect;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import com.google.gson.JsonObject;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;
import org.junit.Before;
import org.junit.Test;

public class CombatTaskTrackerTest
{
	private final CombatTaskTracker tracker = new CombatTaskTracker();
	private Client client;

	@Before
	public void setUp()
	{
		client = mock(Client.class);
		// Reward thresholds as the client reports them.
		when(client.getVarbitValue(VarbitID.CA_THRESHOLD_EASY)).thenReturn(33);
		when(client.getVarbitValue(VarbitID.CA_THRESHOLD_MEDIUM)).thenReturn(115);
		when(client.getVarbitValue(VarbitID.CA_THRESHOLD_HARD)).thenReturn(304);
		when(client.getVarbitValue(VarbitID.CA_THRESHOLD_ELITE)).thenReturn(820);
		when(client.getVarbitValue(VarbitID.CA_THRESHOLD_MASTER)).thenReturn(1465);
		when(client.getVarbitValue(VarbitID.CA_THRESHOLD_GRANDMASTER)).thenReturn(2005);
	}

	private void tasksCompleted(int easy, int medium, int hard, int elite, int master, int grandmaster)
	{
		when(client.getVarbitValue(VarbitID.CA_TOTAL_TASKS_COMPLETED_EASY)).thenReturn(easy);
		when(client.getVarbitValue(VarbitID.CA_TOTAL_TASKS_COMPLETED_MEDIUM)).thenReturn(medium);
		when(client.getVarbitValue(VarbitID.CA_TOTAL_TASKS_COMPLETED_HARD)).thenReturn(hard);
		when(client.getVarbitValue(VarbitID.CA_TOTAL_TASKS_COMPLETED_ELITE)).thenReturn(elite);
		when(client.getVarbitValue(VarbitID.CA_TOTAL_TASKS_COMPLETED_MASTER)).thenReturn(master);
		when(client.getVarbitValue(VarbitID.CA_TOTAL_TASKS_COMPLETED_GRANDMASTER)).thenReturn(grandmaster);
	}

	@Test
	public void ignoresOtherMessages()
	{
		assertNull(tracker.parse(client, "Congratulations, you've completed a quest: Dragon Slayer II."));
		assertNull(tracker.parse(client, "You have completed 80 Master Treasure Trails."));
	}

	@Test
	public void readsTierAndTask()
	{
		tasksCompleted(33, 20, 0, 0, 0, 0); // 33 + 40 = 73 points, past Easy, short of Medium
		final JsonObject task = tracker.parse(client, "Congratulations, you've completed a medium combat task: Lizard Shaman Novice (2 points).");
		assertNotNull(task);
		assertEquals("MEDIUM", task.get("tier").getAsString());
		assertEquals("Lizard Shaman Novice", task.get("task").getAsString());
		assertEquals(73, task.get("totalPoints").getAsInt());
		assertEquals("EASY", task.get("currentTier").getAsString());
		assertFalse(task.has("justCompletedTier"));
	}

	@Test
	public void reportsTheTaskThatUnlockedTheNextTier()
	{
		tasksCompleted(33, 41, 0, 0, 0, 0); // 33 + 82 = 115 points, exactly the Medium threshold
		final JsonObject task = tracker.parse(client, "Congratulations, you've completed a medium combat task: Lizard Shaman Novice.");
		assertNotNull(task);
		assertEquals("MEDIUM", task.get("currentTier").getAsString());
		assertEquals("MEDIUM", task.get("justCompletedTier").getAsString());
	}

	@Test
	public void staysQuietAboutTiersBeforeTheClientHasThresholds()
	{
		when(client.getVarbitValue(VarbitID.CA_THRESHOLD_EASY)).thenReturn(0);
		when(client.getVarbitValue(VarbitID.CA_THRESHOLD_MEDIUM)).thenReturn(0);
		when(client.getVarbitValue(VarbitID.CA_THRESHOLD_HARD)).thenReturn(0);
		when(client.getVarbitValue(VarbitID.CA_THRESHOLD_ELITE)).thenReturn(0);
		when(client.getVarbitValue(VarbitID.CA_THRESHOLD_MASTER)).thenReturn(0);
		when(client.getVarbitValue(VarbitID.CA_THRESHOLD_GRANDMASTER)).thenReturn(0);
		tasksCompleted(10, 0, 0, 0, 0, 0);

		final JsonObject task = tracker.parse(client, "Congratulations, you've completed an easy combat task: Pest Control Novice.");
		assertNotNull(task);
		assertEquals(10, task.get("totalPoints").getAsInt());
		assertFalse(task.has("currentTier"));
		assertFalse(task.has("justCompletedTier"));
	}
}

package com.triglav.clan.collect;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import com.google.gson.JsonObject;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.VarPlayerID;
import org.junit.Test;

public class TrackersTest
{
	@Test
	public void xpMilestoneNeedsACrossingAfterLogin()
	{
		final Client client = mock(Client.class);
		when(client.getSkillExperience(any(Skill.class))).thenReturn(49_999_000);

		final XpMilestoneTracker tracker = new XpMilestoneTracker();
		tracker.prime(client);

		// The burst of StatChanged right after login carries the same XP: nothing happens.
		tracker.onStatChanged(new StatChanged(Skill.ATTACK, 49_999_000, 99, 99));
		assertNull(tracker.onGameTick());

		tracker.onStatChanged(new StatChanged(Skill.ATTACK, 50_000_010, 99, 99));
		final JsonObject milestone = tracker.onGameTick();
		assertNotNull(milestone);
		assertEquals("Attack", milestone.getAsJsonArray("milestoneAchieved").get(0).getAsString());
		assertEquals(50_000_010, milestone.getAsJsonObject("xpData").get("Attack").getAsInt());
		assertEquals(50_000_000, milestone.get("interval").getAsInt());

		// Reported once, and not again until the next 50M.
		assertNull(tracker.onGameTick());
		tracker.onStatChanged(new StatChanged(Skill.ATTACK, 50_000_500, 99, 99));
		assertNull(tracker.onGameTick());
	}

	@Test
	public void collectionLogTotalsStayQuietUntilKnown()
	{
		final Client client = mock(Client.class);
		assertNull(CollectionLogTotals.snapshot(client)); // varps read 0 before the client has them

		when(client.getVarpValue(VarPlayerID.COLLECTION_COUNT)).thenReturn(612);
		when(client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX)).thenReturn(1_699);
		final JsonObject totals = CollectionLogTotals.snapshot(client);
		assertNotNull(totals);
		assertEquals(612, totals.get("completed").getAsInt());
		assertEquals(1699, totals.get("total").getAsInt());

		// A count above the maximum is a half-loaded read, not a result.
		when(client.getVarpValue(VarPlayerID.COLLECTION_COUNT)).thenReturn(2_000);
		assertNull(CollectionLogTotals.snapshot(client));
	}

	@Test
	public void partialQuestStepsAreNotQuests()
	{
		final QuestTracker tracker = new QuestTracker();
		assertEquals(true, tracker.isPartial("You have kind of completed Recipe for Disaster!"));
		assertEquals(false, tracker.isPartial("You have completed The Corsair Curse!"));
		assertEquals("Skrach Uglogwee", QuestTracker.normalise("Skrach 'Bone Crusher' Uglogwee", "x"));
	}
}

