package com.triglav.clan.overview;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonParser;
import org.junit.Test;

public class OverviewTest
{
	@Test
	public void parsesTheSiteResponse()
	{
		final Overview o = Overview.parse(new JsonParser().parse("{"
			+ "\"me\":{\"rsn\":\"K0KS\",\"name\":\"Koks\",\"points\":246},"
			+ "\"events\":[{\"id\":\"e1\",\"title\":\"Raid\",\"type\":\"RAID\",\"startsAt\":\"2026-10-07T18:00:00.000Z\",\"going\":4,\"mine\":\"YES\",\"icon\":\"https://clan.kokalj.dev/api/icon/boss/zulrah\"}],"
			+ "\"lfg\":[{\"id\":\"l1\",\"title\":\"ToA\",\"activity\":\"ToA\",\"startsAt\":\"2026-10-07T19:00:00.000Z\",\"capacity\":4,\"taken\":2,\"mine\":false}],"
			+ "\"myLfg\":[],"
			+ "\"goals\":[{\"id\":\"g\",\"title\":\"10k Vorkath\",\"boss\":\"Vorkath\",\"target\":10000,\"current\":2500,\"done\":false}],"
			+ "\"deaths\":{\"month\":3,\"valueLost\":4500000}}").getAsJsonObject());

		assertEquals("K0KS", o.rsn);
		assertEquals(246, o.points);
		assertEquals(1, o.events.size());
		assertTrue(o.events.get(0).mine);
		assertEquals(4, o.events.get(0).going);
		assertEquals("https://clan.kokalj.dev/api/icon/boss/zulrah", o.events.get(0).icon);
		assertEquals(null, o.lfg.get(0).icon);
		assertEquals(2, o.lfg.get(0).taken);
		assertEquals(2500, o.goals.get(0).current);
		assertEquals(3, o.deathsThisMonth);
		assertEquals(4_500_000L, o.valueLostThisMonth);
	}

	@Test
	public void anEmptyResponseIsHarmless()
	{
		final Overview o = Overview.parse(new JsonParser().parse("{}").getAsJsonObject());
		assertEquals(null, o.rsn);
		assertTrue(o.events.isEmpty() && o.lfg.isEmpty() && o.myLfg.isEmpty() && o.goals.isEmpty());
	}
}

package com.triglav.clan.remind;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.triglav.clan.overview.Overview;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class GearCheckTest
{
	private static Overview.MyLfg lfg(String gearJson)
	{
		final JsonObject body = new JsonParser().parse("{\"myLfg\":[{\"id\":\"l1\",\"title\":\"Zulrah\",\"activity\":\"Zulrah\","
			+ "\"startsAt\":\"2026-10-07T20:00:00.000Z\",\"gear\":" + gearJson + "}]}").getAsJsonObject();
		return Overview.parse(body).myLfg.get(0);
	}

	private static final String SETUP = "{\"title\":\"Zulrah mage\",\"equipment\":[{\"id\":12899,\"name\":\"Trident of the swamp\"},{\"id\":4151,\"name\":\"Abyssal whip\"}],"
		+ "\"inventory\":[{\"id\":385,\"name\":\"Shark\",\"qty\":3},{\"id\":3024,\"name\":\"Super restore(4)\",\"qty\":2}]}";

	@Test
	public void everythingBroughtMeansNothingMissing()
	{
		final Map<Integer, Integer> have = new HashMap<>();
		have.put(12899, 1);
		have.put(4151, 1);
		have.put(385, 5);
		have.put(3024, 2);
		assertTrue(GearCheck.missing(lfg(SETUP), have, id -> id).isEmpty());
	}

	@Test
	public void listsMissingItemsAndShortfalls()
	{
		final Map<Integer, Integer> have = new HashMap<>();
		have.put(12899, 1);
		have.put(385, 1); // 3 sharks wanted, 1 carried
		final List<String> missing = GearCheck.missing(lfg(SETUP), have, id -> id);
		assertEquals(Arrays.asList("Abyssal whip", "Shark x2", "Super restore(4) x2"), missing);
	}

	@Test
	public void aWornItemCountsEvenIfTheSetupHasItInTheInventory()
	{
		final Map<Integer, Integer> have = new HashMap<>();
		have.put(4151, 1);
		final Overview.MyLfg mine = lfg("{\"title\":\"x\",\"equipment\":[],\"inventory\":[{\"id\":4151,\"name\":\"Abyssal whip\"}]}");
		assertTrue(GearCheck.missing(mine, have, id -> id).isEmpty());
	}

	@Test
	public void canonicalIdsMatchVariants()
	{
		final Map<Integer, Integer> have = new HashMap<>();
		have.put(4151, 1); // the canonical id is what the carried side is keyed by
		final Overview.MyLfg mine = lfg("{\"title\":\"x\",\"equipment\":[{\"id\":4152,\"name\":\"Abyssal whip\"}],\"inventory\":[]}");
		assertTrue(GearCheck.missing(mine, have, id -> id == 4152 ? 4151 : id).isEmpty());
	}

	@Test
	public void lfgWithoutASetupHasNothingToCheck()
	{
		final JsonObject body = new JsonParser().parse("{\"myLfg\":[{\"id\":\"l\",\"title\":\"t\",\"activity\":\"a\",\"startsAt\":\"2026-10-07T20:00:00.000Z\",\"gear\":null}]}").getAsJsonObject();
		final Overview.MyLfg mine = Overview.parse(body).myLfg.get(0);
		assertEquals(false, mine.hasGear());
		assertTrue(GearCheck.missing(mine, Collections.emptyMap(), id -> id).isEmpty());
	}
}

package com.triglav.clan.share;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.EnumSet;
import net.runelite.api.Client;
import net.runelite.api.WorldType;
import net.runelite.api.gameval.VarbitID;
import org.junit.Before;
import org.junit.Test;

public class LocationSharerTest
{
	private Client client;

	@Before
	public void setUp()
	{
		client = mock(Client.class);
		when(client.getWorldType()).thenReturn(EnumSet.of(WorldType.MEMBERS));
	}

	@Test
	public void anOrdinaryWorldMayShare()
	{
		assertFalse(LocationSharer.isSensitive(client, false));
	}

	@Test
	public void theWildernessNeverShares()
	{
		when(client.getVarbitValue(VarbitID.INSIDE_WILDERNESS)).thenReturn(1);
		assertTrue(LocationSharer.isSensitive(client, false));
	}

	@Test
	public void instancesNeverShareEvenWithTheExtraTick()
	{
		when(client.isInInstancedRegion()).thenReturn(true);
		assertTrue(LocationSharer.isSensitive(client, false));
		assertTrue(LocationSharer.isSensitive(client, true));
	}

	@Test
	public void theExtraTickAllowsTheWildernessAndPvpWorlds()
	{
		when(client.getVarbitValue(VarbitID.INSIDE_WILDERNESS)).thenReturn(1);
		assertTrue(LocationSharer.isSensitive(client, false));
		assertFalse(LocationSharer.isSensitive(client, true));

		when(client.getVarbitValue(VarbitID.INSIDE_WILDERNESS)).thenReturn(0);
		when(client.getWorldType()).thenReturn(EnumSet.of(WorldType.MEMBERS, WorldType.DEADMAN));
		assertTrue(LocationSharer.isSensitive(client, false));
		assertFalse(LocationSharer.isSensitive(client, true));
	}

	@Test
	public void pvpStyleWorldsNeverShare()
	{
		for (WorldType type : new WorldType[]{WorldType.PVP, WorldType.BOUNTY, WorldType.HIGH_RISK, WorldType.DEADMAN, WorldType.LAST_MAN_STANDING, WorldType.PVP_ARENA, WorldType.TOURNAMENT_WORLD})
		{
			when(client.getWorldType()).thenReturn(EnumSet.of(WorldType.MEMBERS, type));
			assertTrue(type + " should be sensitive", LocationSharer.isSensitive(client, false));
		}
	}
}

